// Machine-assisted translation, unreviewed. French TL;DRs keyed by entity id.
// Coverage: all cancers. Drug and brand names stay in Latin script.
export const tldr_fr: Record<string, string> = {
  // ---- cancers ----
  tnbc: "Un cancer du sein dépourvu des trois récepteurs (œstrogène, progestérone, HER2) par lesquels on traite les autres cancers du sein. Ce fut le sous-type le plus difficile pendant des décennies ; depuis 2020, l'immunothérapie et les ADC ont changé la donne.",
  "breast-hr-positive": "Le cancer du sein le plus fréquent, alimenté par les œstrogènes. Traité pendant des années par des comprimés bloquant les hormones, aujourd'hui rejoints par les inhibiteurs de CDK4/6, les médicaments de la voie PI3K, les dégradeurs et les ADC.",
  "breast-her2-positive": "Autrefois le sous-type le plus agressif, aujourd'hui l'un des plus traitables grâce au trastuzumab et, plus récemment, à Enhertu.",
  nsclc: "Le cancer qui tue le plus et le terrain d'essai de la médecine de précision : une douzaine de mutations ciblables, l'immunothérapie pour le reste, et les ADC et bispécifiques qui arrivent maintenant.",
  sclc: "Un cancer du poumon à croissance rapide qui répond à la chimiothérapie puis récidive vite. Après 30 ans sans progrès, les engageurs de lymphocytes T et les ADC font enfin bouger les choses.",
  colorectal: "Le cancer où le dépistage marche le mieux et où l'immunothérapie peut faire disparaître complètement certaines tumeurs, alors que la plupart des maladies métastatiques dépendent encore de la chimiothérapie.",
  pancreatic: "Le cancer courant le plus mortel. Presque toutes les tumeurs portent une mutation de KRAS et, pour la première fois, des médicaments dirigés contre elle sont en essais pivots.",
  gastric: "Un cancer avec trois nouvelles cibles en cinq ans : Claudine 18.2, FGFR2b et HER2 avec de nouveaux ADC, plus l'immunothérapie en première ligne.",
  esophageal: "Le cancer de l'œsophage est en réalité deux maladies dans un même organe : le carcinome épidermoïde, dominant en Asie, et l'adénocarcinome, dominant en Occident et traité comme le cancer gastrique. L'immunothérapie est désormais standard, et l'ADC bispécifique iza-bren a obtenu une phase 3 positive dans le type épidermoïde en 2026.",
  hcc: "Le cancer du foie se développe presque toujours dans un foie déjà abîmé par une hépatite, l'alcool ou la stéatose. C'est l'un des cancers les plus évitables, et depuis 2020 les combinaisons d'immunothérapie ont à peu près doublé la survie des formes avancées.",
  cholangiocarcinoma: "Le cholangiocarcinome est un cancer des voies biliaires ou de la vésicule. Rare et souvent découvert tard, il s'est révélé porter plus de mutations ciblables que presque tout autre cancer digestif, et l'immunothérapie s'ajoute désormais à la chimiothérapie dès le premier traitement.",
  prostate: "Le berceau de la théranostique : le TEP au PSMA le trouve, les radioligands du PSMA le traitent. L'hormonothérapie reste la base, avec des inhibiteurs de PARP et d'AKT ajoutés selon le génotype.",
  urothelial: "Le cancer de la vessie est passé de 40 ans de cisplatine à une association ADC-immunothérapie qui a presque doublé la survie, et en 2026 à la première approbation guidée par un test sanguin.",
  rcc: "Le cancer du rein est le lieu où les antiangiogéniques et l'immunothérapie se sont rejoints, et où une voie de détection de l'oxygène couronnée par un Nobel a donné un médicament, le belzutifan.",
  ovarian: "Souvent découvert tard. Les inhibiteurs de PARP ont transformé le traitement d'entretien, et des ADC contre le récepteur des folates et CDH6 arrivent pour la maladie résistante au platine.",
  endometrial: "Le cancer gynécologique où l'immunothérapie a eu le plus grand impact, guidée par la classification moléculaire.",
  cervical: "Un cancer que la vaccination anti-HPV et le dépistage pourraient éliminer. Pour celles qui le développent, l'immunothérapie et un ADC dirigé contre le facteur tissulaire ont amélioré la survie.",
  melanoma: "Le cancer qui a prouvé que l'immunothérapie fonctionne : la moitié des patients avancés vivent désormais 10 ans. Aussi le premier avec une thérapie TIL approuvée, un virus oncolytique et un vaccin personnalisé avec une phase 3 positive.",
  glioblastoma: "Le glioblastome est la tumeur cérébrale la plus mortelle, à peine améliorée depuis 2005. Les gliomes de bas grade avec mutation d'IDH, eux, ont reçu leur premier médicament ciblé en 2024.",
  "head-and-neck": "Cancers de la bouche et de la gorge, de plus en plus causés par le HPV. L'immunothérapie est la première ligne en maladie avancée et s'utilise désormais avant la chirurgie.",
  sarcoma: "Des dizaines de cancers rares de l'os et des tissus conjonctifs. Le GIST fut la première tumeur solide guérie en pratique par un comprimé ciblé ; le sarcome synovial a reçu la première thérapie TCR-T.",
  thyroid: "Le cancer de la thyroïde se guérit généralement par chirurgie et iode radioactif, la théranostique originelle. Les rares formes agressives répondent aux inhibiteurs de RET et de BRAF.",
  neuroendocrine: "Une famille de tumeurs généralement lentes qui naissent dans les cellules productrices d'hormones de l'intestin, du pancréas et des poumons. Elles ont ouvert la voie à l'idée d'utiliser la même molécule pour voir une tumeur à l'imagerie puis la traiter par radiation.",
  mesothelioma: "Un cancer de la plèvre causé par l'amiante. Les doublets d'immunothérapie ont remplacé la chimiothérapie en 2020, et un CAR-T contre la mésothéline est à l'étude.",
  neuroblastoma: "Un cancer des cellules nerveuses de l'enfant où les anticorps anti-GD2 et, récemment, les CAR-T anti-GD2 ont amélioré la survie dans la maladie à haut risque.",
  aml: "La leucémie aiguë myéloïde est un cancer du sang agressif où, après 40 ans de la même chimiothérapie, une vague de médicaments ciblés est arrivée (FLT3, IDH, BCL-2, ménine).",
  "all-leukemia": "La leucémie aiguë lymphoblastique est l'histoire à succès du cancer de l'enfant, et fut la première maladie traitée par CAR-T et par un engageur de lymphocytes T.",
  cll: "Une leucémie lente qui n'a plus besoin de chimiothérapie : les inhibiteurs de BTK et le vénétoclax la contrôlent pendant des années, souvent en cures de durée fixe.",
  dlbcl: "Le lymphome diffus à grandes cellules B (DLBCL) est un lymphome agressif mais curable. Le CAR-T guérit environ 40 % des patients en rechute, et des bispécifiques prêts à l'emploi sont désormais approuvés.",
  "hodgkin-lymphoma": "Le lymphome de Hodgkin est l'un des cancers les plus curables ; l'objectif est désormais de guérir avec moins de toxicité, avec le brentuximab et, depuis 2026, le nivolumab en première ligne.",
  "multiple-myeloma": "Le myélome multiple est un cancer des plasmocytes qui compte plus de nouvelles classes de médicaments que tout autre : inhibiteurs du protéasome, IMiD, anticorps anti-CD38, CAR-T anti-BCMA, bispécifiques et un ADC.",
  adrenocortical: "Le carcinome corticosurrénalien est un cancer rare et agressif de la glande surrénale qui produit souvent trop d'hormones. La chirurgie est la seule guérison, le mitotane est le seul médicament qui lui soit propre (avec une vraie toxicité), et la chimiothérapie ou l'immunothérapie n'aident qu'une minorité.",
  anal: "Un cancer du canal anal causé par le HPV, généralement guéri sans chirurgie par l'association de chimiothérapie et de radiothérapie. La prévention (vaccination anti-HPV, dépistage des groupes à risque) et l'immunothérapie pour la maladie avancée sont les nouveaux fronts.",
  appendiceal: "Des tumeurs rares de l'appendice, allant de proliférations lentes qui produisent du mucus et remplissent l'abdomen (pseudomyxome péritonéal) à des adénocarcinomes agressifs. Les formes lentes sont traitées par une chirurgie étendue avec chimiothérapie chauffée dans l'abdomen ; les rapides comme un cancer du côlon.",
  "basal-cell-carcinoma": "Le carcinome basocellulaire est le cancer le plus fréquent de tous, causé par le soleil et presque jamais mortel. Presque tous sont retirés chirurgicalement ; les rares cas avancés sont traités par des médicaments bloquant la voie de signalisation hedgehog, puis par immunothérapie si ceux-ci échouent.",
  bpdcn: "Un cancer du sang très rare et agressif issu des précurseurs des cellules dendritiques, qui se manifeste souvent par des lésions cutanées ressemblant à des bleus. Deux médicaments dirigés contre CD123 sont les premières thérapies ciblées ; la greffe reste nécessaire pour guérir.",
  "cancer-of-unknown-primary": "Un cancer découvert déjà disséminé, dont les médecins ne trouvent pas l'origine. La plupart des cas reçoivent une chimiothérapie générale et évoluent mal ; les tests moléculaires pour deviner l'origine ou trouver une cible changent lentement la situation.",
  cml: "La leucémie myéloïde chronique est un cancer du sang provoqué par un seul gène de fusion, BCR-ABL. L'imatinib, en 2001, a transformé une maladie dont la survie médiane était d'environ cinq ans en une maladie avec laquelle la plupart des gens vivent, et beaucoup peuvent désormais arrêter tout traitement.",
  "cutaneous-scc": "Un cancer de la peau très fréquent lié au soleil, presque toujours guéri par son ablation. La petite fraction qui s'enfonce ou se dissémine répond désormais bien à l'immunothérapie anti-PD-1, également donnée après la chirurgie dans les cas à haut risque.",
  "ewing-sarcoma": "Le sarcome d'Ewing est un cancer de l'os et des tissus mous de l'adolescent, provoqué par un seul gène de fusion, EWSR1-FLI1. Une chimiothérapie intensive avec chirurgie ou radiothérapie guérit la plupart des cas localisés ; la maladie disséminée et la rechute restent très difficiles, et la protéine de fusion elle-même a résisté à la conception de médicaments.",
  "follicular-lymphoma": "Le lymphome folliculaire est le lymphome lent le plus fréquent. La plupart des gens vivent de nombreuses années avec, traités seulement quand il pose problème ; il se contrôle à répétition mais se guérit rarement, et une minorité se transforme en lymphome agressif.",
  gist: "Le GIST est un sarcome de la paroi digestive presque toujours provoqué par une mutation de KIT ou de PDGFRA. Il a prouvé qu'un comprimé peut contrôler une tumeur solide : l'imatinib a fait passer la survie médiane d'environ un an à huit ans ou plus, et la mutation dicte désormais le médicament à utiliser.",
  "gestational-trophoblastic": "Des cancers qui naissent du tissu placentaire après une grossesse. Ils produisent une hormone (hCG) qui sert de test sanguin parfait, et ils furent le premier cancer solide jamais guéri par chimiothérapie. L'immunothérapie sauve désormais les rares cas résistants aux médicaments.",
  "hairy-cell-leukemia": "La leucémie à tricholeucocytes est une leucémie B rare et lente avec une seule mutation caractéristique (BRAF V600E), exceptionnellement curable : une semaine d'analogue des purines met la plupart des gens en rémission pour des années, et les médicaments anti-BRAF sauvent ceux qui rechutent.",
  hepatoblastoma: "Un cancer du foie du jeune enfant, hautement curable par chimiothérapie au cisplatine et chirurgie, y compris la greffe de foie quand la tumeur ne peut pas être retirée. Un succès récent a été de prouver qu'un simple antidote prévient la perte d'audition permanente causée par le cisplatine.",
  "kaposi-sarcoma": "Un cancer des vaisseaux sanguins causé par un herpèsvirus, rendu célèbre par l'épidémie de sida. Chez les personnes vivant avec le VIH, le traitement antirétroviral seul le fait souvent régresser ; la chimiothérapie comme la doxorubicine liposomale ou le paclitaxel traite la maladie avancée, et il reste un cancer majeur en Afrique.",
  "mantle-cell-lymphoma": "Un lymphome B peu fréquent, provoqué par la cycline D1, qui évoluait mal chez presque tout le monde. Les inhibiteurs de BTK, le CAR-T et désormais les médicaments anti-BCL2 l'ont fait passer de la chimiothérapie plus greffe aux combinaisons ciblées.",
  medulloblastoma: "Le médulloblastome est la tumeur cérébrale maligne la plus fréquente de l'enfant, née dans le cervelet. Chirurgie, irradiation de tout le cerveau et de la moelle, et chimiothérapie guérissent environ 70 %, à un lourd prix pour la pensée et la croissance ; le traitement est désormais adapté à quatre sous-groupes moléculaires pour que les enfants à faible risque en reçoivent moins.",
  "merkel-cell-carcinoma": "Le carcinome à cellules de Merkel est un cancer de la peau rare et à croissance rapide, généralement causé par un virus courant (le polyomavirus des cellules de Merkel) ou par les dégâts du soleil. Presque intraitable une fois disséminé, il répond désormais durablement à l'immunothérapie anti-PD-1/PD-L1 chez environ la moitié des patients.",
  mds: "Des maladies de la moelle osseuse où les cellules sanguines sont mal fabriquées et trop peu atteignent le sang ; un tiers évolue vers une leucémie aiguë. Le traitement va des transfusions et facteurs de croissance aux agents hypométhylants et, pour les patients en forme, à la greffe.",
  "myeloproliferative-neoplasms": "Des cancers du sang à évolution lente dans lesquels la moelle produit trop de globules rouges, de plaquettes ou de tissu cicatriciel. Presque tous portent une mutation de JAK2, CALR ou MPL. Le traitement vise à prévenir les caillots, à contrôler les symptômes et, dans la myélofibrose, à réduire la rate.",
  nasopharyngeal: "Un cancer de l'arrière du nez, dû en grande partie au virus d'Epstein-Barr et fréquent dans le sud de la Chine et en Asie du Sud-Est. La radiothérapie guérit la plupart des cas précoces ; l'ajout de chimiothérapie et, récemment, d'immunothérapie anti-PD-1 a amélioré les résultats en maladie avancée, et un test sanguin de l'ADN viral peut le détecter tôt.",
  osteosarcoma: "L'ostéosarcome est le cancer de l'os le plus fréquent, surtout chez les adolescents. Chimiothérapie plus chirurgie guérissent environ deux tiers des cas non disséminés, mais la survie n'a pas progressé en 30 ans et aucun nouveau médicament n'a réussi dans un grand essai.",
  "peripheral-t-cell-lymphoma": "Les lymphomes T périphériques sont des lymphomes des lymphocytes T plutôt que B. Ils sont plus rares, plus variés et, à part quelques sous-types, plus difficiles à traiter que les lymphomes B ; plusieurs nouveaux médicaments n'aident que des sous-types précis.",
  "primary-cns-lymphoma": "Le lymphome primitif du système nerveux central est un lymphome confiné au cerveau, aux yeux et au liquide céphalorachidien. Contrairement à la plupart des tumeurs cérébrales, il est chimiosensible : un traitement à base de méthotrexate à haute dose guérit une minorité substantielle, et la consolidation par autogreffe a remplacé l'irradiation du cerveau entier chez les patients en forme.",
  retinoblastoma: "Un cancer de l'œil du nourrisson causé par la perte du gène RB1, le premier gène suppresseur de tumeur jamais découvert. Dans les pays riches, presque tous les enfants survivent et la plupart des yeux sont sauvés par une chimiothérapie délivrée par l'artère de l'œil ; dans les pays pauvres, beaucoup d'enfants meurent encore parce qu'il est découvert trop tard.",
  rhabdomyosarcoma: "Un cancer des tissus mous de l'enfant, fait de cellules ressemblant à du muscle, qui peut apparaître de l'orbite à la vessie. La plupart des enfants sont guéris par chimiothérapie, chirurgie et radiothérapie, et un gène de fusion (PAX-FOXO1) décide désormais de l'intensité du traitement.",
  "salivary-gland": "Les cancers des glandes salivaires forment une famille de plus de 20 cancers rares, chacun avec son propre comportement et souvent sa propre fusion génique. Chirurgie et radiothérapie traitent la plupart ; le traitement médicamenteux est désormais choisi selon le sous-type, des anti-HER2 ou anti-androgènes aux inhibiteurs de NTRK.",
  testicular: "Les tumeurs germinales du testicule sont le cancer solide de l'adulte le plus curable. La chimiothérapie à base de cisplatine guérit la grande majorité, même en cas de dissémination étendue ; la recherche actuelle cherche à traiter moins la majorité tout en sauvant les rares patients qui rechutent.",
  "thymic-epithelial": "Le thymome et le carcinome thymique sont des tumeurs rares du thymus, dans le thorax. Les thymomes évoluent lentement, causent souvent des maladies auto-immunes comme la myasthénie et se guérissent généralement par chirurgie ; les carcinomes thymiques se comportent comme d'autres cancers agressifs et disposent de peu de médicaments efficaces.",
  "uveal-melanoma": "Un mélanome à l'intérieur de l'œil, biologiquement sans rapport avec le mélanome cutané : des mutations différentes, pas de réponse à l'immunothérapie standard, et une tendance à se disséminer au foie des années plus tard. Le tebentafusp est le premier médicament à avoir prolongé la survie dans la maladie métastatique.",
  vulvar: "Un cancer peu fréquent des organes génitaux externes avec deux causes distinctes : l'infection à HPV chez les femmes jeunes et l'inflammation cutanée chronique chez les femmes âgées. La chirurgie reste le pilier, et la biopsie du ganglion sentinelle l'a rendue bien moins mutilante.",
  waldenstrom: "Un lymphome lent qui produit un anticorps IgM anormal, causant un sang épais, une anémie et des atteintes nerveuses. Presque tous les cas partagent une mutation (MYD88 L265P), et les inhibiteurs de BTK le contrôlent pendant des années.",
  "wilms-tumor": "La tumeur de Wilms est un cancer du rein du jeune enfant et l'une des réussites de l'oncologie pédiatrique : la chirurgie plus quelques mois de chimiothérapie guérissent environ neuf enfants sur dix. Les essais actuels visent à donner presque aucune chimiothérapie aux enfants à plus faible risque tout en repérant les rares cas à biologie agressive.",
  // ---- most-connected records without translations (2026-09 wave) ----
  aacr: "L'AACR est la plus ancienne et la plus grande société de recherche sur le cancer ; c'est lors de son congrès d'avril qu'apparaissent la science à un stade précoce et les premières données chez l'humain.",
  abbvie: "AbbVie possède Venclexta et Elahere, et a racheté Capstan, la principale entreprise de CAR-T in vivo.",
  abemaciclib: "L'abemaciclib a été le premier inhibiteur de CDK4/6 approuvé après la chirurgie pour le cancer du sein hormonosensible à haut risque.",
  abiraterone: "Abiraterone est un comprimé qui arrête la production de testostérone partout dans l'organisme, y compris à l'intérieur de la tumeur. Découvert à l'Institute of Cancer Research, il est aujourd'hui générique et utilisé dès le premier diagnostic de métastases.",
  acalabrutinib: "Acalabrutinib est un bloqueur de BTK plus propre, avec moins de problèmes cardiaques et de saignements que l'ibrutinib. En février 2026, il est devenu la moitié du premier traitement de la leucémie lymphoïde chronique (CLL) entièrement par voie orale et de durée fixe.",
  "accelerated-approval": "Approbation de la FDA fondée sur des preuves précoces (comme la réduction de la tumeur), à condition qu'un essai de confirmation suive.",
  "active-surveillance": "Pour le cancer de la prostate à faible risque, une surveillance par PSA, MRI et biopsies répétées au lieu d'un traitement, car la plupart de ces cancers ne causent jamais de dommages.",
  actrec: "Le campus de recherche et développement du Tata Memorial Centre, où a été mise au point la première thérapie CAR-T indigène de l'Inde et où sont conçus des essais à faible coût.",
  adagrasib: "Adagrasib a été le deuxième inhibiteur de KRAS G12C, avec une longue demi-vie et une pénétration dans le cerveau, et il est approuvé dans le cancer du poumon et le cancer colorectal.",
  adc: "Un conjugué anticorps-médicament est un missile guidé : un anticorps se dirige vers la cellule tumorale, y est absorbé, puis libère une chimiothérapie si puissante qu'elle ne pourrait jamais être administrée seule.",
  "adc-generations": "Vingt-cinq ans d'efforts pour que la chimiothérapie ne frappe que les cellules cancéreuses, du premier ADC instable aux blockbusters de troisième génération d'aujourd'hui et à la quatrième génération actuellement en essais.",
  "adc-sequencing": "La question encore ouverte de savoir si un second ADC fonctionne après l'échec du premier, surtout lorsque les deux transportent le même type de charge utile.",
  adcs: "Un anticorps qui trouve la tumeur, porteur d'une dose minuscule de chimiothérapie très puissante qui n'est libérée qu'à l'intérieur de celle-ci.",
  "ai-computation": "Des logiciels qui lisent les images médicales et les lames, prédisent les résultats, conçoivent des médicaments et orientent les patients vers des essais.",
  "ai-drug-design": "Utiliser l'apprentissage automatique pour choisir des cibles, concevoir des molécules et des anticorps, et prédire quel ADC fonctionnera.",
  "ai-oncology-clinic": "Comment l'IA passe de lecteurs d'images et de lames limités à une seule tâche à des systèmes qui pèsent tout ce qui concerne un patient, et ce que les régulateurs et les preuves exigent encore.",
  "ai-trial-matching": "Des logiciels, de plus en plus fondés sur des LLM, qui lisent le dossier d'un patient et trouvent les essais ou les options recommandées par les guides de pratique auxquels il est admissible.",
  akt: "AKT est une kinase de survie centrale située en aval de PI3K, bloquée par le capivasertib dans le cancer du sein et désormais dans le cancer de la prostate.",
  alk: "Une fusion de gènes présente dans environ 5 % des cancers du poumon, qui répond de façon spectaculaire à des comprimés, désormais pendant de nombreuses années.",
  "allogeneic-cell-therapy": "Des thérapies cellulaires fabriquées à l'avance à partir de donneurs sains, pour que les patients n'aient pas à attendre que leurs propres cellules soient modifiées.",
  "allogeneic-hsct": "Remplacer le système sanguin d'un patient par celui d'un donneur, afin que les cellules immunitaires du donneur traquent toute leucémie restante. C'est encore le seul traitement curatif pour de nombreuses leucémies à haut risque.",
  amgen: "Amgen a inventé le format BiTE d'engageurs de cellules T et le premier inhibiteur de KRAS.",
  amivantamab: "Un anticorps à deux bras qui bloque EGFR et son partenaire d'échappement MET, désormais utilisé en première ligne avec le lazertinib dans le cancer du poumon avec mutation d'EGFR.",
  ampullary: "Le cancer ampullaire naît à l'endroit où les canaux biliaire et pancréatique se déversent dans l'intestin grêle. Comme il bloque tôt l'écoulement de la bile, il est souvent détecté alors qu'il est encore opérable, et l'intervention de Whipple guérit une bonne part des patients. Les tumeurs sont de deux types, de type intestinal et de type pancréatique, et la chimiothérapie est de plus en plus choisie selon celui que le pathologiste observe.",
  "androgen-deprivation": "La privation androgénique abaisse la testostérone ou bloque son récepteur, et constitue le fondement du traitement du cancer de la prostate depuis 1941 (prix Nobel 1966).",
  "androgen-receptor": "L'interrupteur hormonal qui alimente le cancer de la prostate, attaqué par la castration et par des comprimés qui bloquent le récepteur.",
  "angiogenic-switch": "Une tumeur ne peut pas grossir au-delà de quelques millimètres sans son propre apport sanguin. L'« interrupteur » bascule lorsque les signaux appelant de nouveaux vaisseaux (VEGF, FGF, angiopoïétine) l'emportent sur ceux qui les freinent (thrombospondine). Les vaisseaux qui en résultent sont perméables et désordonnés, ce qui prive la tumeur d'oxygène, bloque les médicaments et offre aux cellules cancéreuses une porte de sortie.",
  antiangiogenic: "La thérapie anti-angiogénique coupe l'apport sanguin de la tumeur ; elle est aujourd'hui surtout utilisée pour aider l'immunothérapie à mieux fonctionner.",
  "antigen-presentation-immunoediting": "Comment le système immunitaire voit le cancer, et comment le cancer apprend à se cacher. Les tumeurs exposent des fragments de leurs protéines sur les molécules du MHC ; les cellules T tuent celles qu'elles reconnaissent ; les survivantes sont celles qui ont cessé de montrer des fragments ou qui ont activé des freins.",
  anzup: "Le groupe australien d'essais en cancérologie génito-urinaire à l'origine de TheraP et proPSMA, les essais qui ont fait connaître l'imagerie PSMA et le traitement par lutétium-PSMA.",
  "apoptosis-bcl2": "L'apoptose intrinsèque est l'interrupteur d'autodestruction de la cellule. BCL-2 le maintient fermé ; BAX et BAK l'ouvrent. Le venetoclax décroche BCL-2 pour que l'interrupteur puisse se déclencher.",
  "ar-signaling": "La signalisation du récepteur des androgènes est le moteur du cancer de la prostate. La testostérone est transformée en DHT, se lie au récepteur des androgènes et active les gènes de croissance. La castration supprime le carburant ; les nouveaux comprimés bloquent le récepteur ou l'enzyme qui fabrique du carburant à l'intérieur de la tumeur.",
  "armored-car": "Des cellules CAR-T améliorées qui sécrètent aussi des stimulants immunitaires, résistent à l'épuisement ou ne s'activent qu'en présence de deux signaux.",
  asco: "L'ASCO est la plus grande société professionnelle d'oncologie du monde ; son congrès annuel, chaque mois de juin, est le lieu où la plupart des essais qui changent la pratique clinique sont présentés pour la première fois.",
  "aspirin-cancer-prevention": "L'aspirine quotidienne à faible dose réduit le risque de cancer de l'intestin chez les personnes atteintes du syndrome de Lynch et semble diminuer les récidives des cancers de l'intestin porteurs d'une mutation particulière. Chez les personnes âgées en bonne santé, elle a fait plus de mal que de bien.",
  astrazeneca: "AstraZeneca est le grand laboratoire pharmaceutique le plus engagé dans les ADC, copropriétaire d'Enhertu et de Datroway, avec de forts paris sur les thérapies ciblées et la radiopharmacie.",
  atezolizumab: "Un inhibiteur de PD-L1 utilisé dans les cancers du poumon, du foie et de la vessie. En 2026, il est devenu le premier médicament approuvé sur la base d'un test sanguin montrant un reste de cancer après une chirurgie de la vessie.",
  atr: "ATR est une kinase qui donne l'alerte en cas de dommages à l'ADN. La bloquer fait s'effondrer les tumeurs dont les systèmes de réparation sont défaillants, sous le poids de leur propre stress de réplication.",
  atrt: "L'ATRT est une tumeur cérébrale agressive des bébés et des tout-petits, causée par la perte d'un seul gène, SMARCB1, qui fait partie de la machinerie qui ouvre et ferme l'ADN. Une chimiothérapie intensive avec sauvetage par cellules souches, et une radiothérapie lorsque l'âge le permet, guérissent aujourd'hui une part significative des enfants qui avaient autrefois peu de chances, et des médicaments visant la conséquence épigénétique de la perte de SMARCB1 (les inhibiteurs d'EZH2) sont en cours d'essais.",
  "autologous-stem-cell-transplant": "On prélève les cellules souches sanguines du patient lui-même, on administre une dose très élevée de chimiothérapie qui détruirait autrement la moelle, puis on lui réinjecte ses cellules pour la reconstruire.",
  "axicabtagene-ciloleucel": "Une CAR-T anti-CD19 qui guérit environ 40 % des patients atteints d'un lymphome à grandes cellules B chez qui tout avait échoué, et qui a surpassé la greffe en deuxième ligne.",
  azacitidine: "Une chimiothérapie douce qui réactive des gènes mis en silence. Associée au venetoclax, elle est devenue le traitement standard des personnes âgées atteintes d'AML qui ne peuvent pas recevoir de traitement intensif.",
  "b-aging-comorbidity": "La plupart des personnes atteintes de cancer ont plus de 65 ans, mais la plupart des patients des essais sont plus jeunes et en meilleure forme. Nous devinons comment traiter la majorité.",
  "b-ai-validation": "Des milliers de modèles d'IA en cancérologie sont publiés ; une poignée est utilisée en clinique, et encore moins ont démontré qu'ils aident les patients.",
  "b-biomarker-validation": "Les tests qui décident qui reçoit un médicament ne sont souvent pas validés de manière prospective et sont mesurés différemment dans chaque laboratoire.",
  "b-brain-delivery": "La plupart des médicaments ne peuvent pas pénétrer dans le cerveau, si bien que les tumeurs cérébrales et les métastases cérébrales accusent un retard par rapport à toutes les autres localisations.",
  "b-cachexia-supportive": "Le dépérissement et l'intolérance aux traitements empêchent de nombreux patients de recevoir les doses qui seraient efficaces. Soigner le patient, et pas seulement la tumeur, reste très en retard.",
  "b-care-fragmentation": "Les patients passent entre les mailles du filet entre spécialistes, attendent des orientations et, souvent, ne reçoivent pas le traitement que les recommandations prévoient.",
  "b-combination-space": "Il existe des milliers de paires et de séquences de médicaments possibles. Les essais peuvent en tester quelques dizaines par an.",
  "b-data-silos": "Dossiers, imageries, génomes et résultats sont stockés dans des systèmes séparés qui ne communiquent pas entre eux. L'expérience de chaque patient est perdue pour le suivant.",
  "b-dormancy-mrd": "Après un traitement « réussi », des cellules peuvent rester endormies pendant des années puis provoquer une rechute. Nous les détectons à peine et ne savons pas les cibler.",
  "b-dose-optimisation": "La plupart des doses de médicaments ont été choisies comme la plus forte qu'une personne peut tolérer, ce qui est souvent plus que nécessaire.",
  "b-drug-pricing": "Les nouveaux médicaments contre le cancer coûtent couramment plus de 150 000 dollars par an, souvent pour quelques mois de bénéfice. Les systèmes de santé ne peuvent pas les payer et les patients se ruinent.",
  "b-early-detection": "Le dépistage n'existe que pour quelques cancers. Les cancers du pancréas, de l'ovaire, du foie, de l'œsophage et la plupart des cancers du poumon sont découverts quand la guérison est peu probable.",
  "b-funding-allocation": "L'argent va aux cancers et aux questions faciles ou à la mode, pas à ceux qui pèsent le plus lourd ni là où chaque dollar ferait le plus de bien.",
  "b-generic-repurposing": "Les vieux médicaments bon marché qui montrent des signes d'activité anticancéreuse n'obtiennent jamais les essais dont ils ont besoin, parce que personne ne tire profit du résultat.",
  "b-global-access": "Sept décès par cancer sur dix surviennent dans des pays à revenu faible ou intermédiaire, où la radiothérapie, l'anatomopathologie, la chirurgie et les médicaments sont rares.",
  "b-hereditary-risk": "La plupart des personnes porteuses d'un gène de cancer à haut risque l'ignorent jusqu'à ce qu'elles-mêmes ou un proche développent un cancer.",
  "b-immunotherapy-response": "Les inhibiteurs de points de contrôle guérissent certains patients et ne font rien pour la plupart. Nous ne savons toujours pas distinguer les uns des autres avant de traiter.",
  "b-incentive-misalignment": "Le système paie autant pour un médicament qui apporte deux mois que pour une guérison, alors les entreprises se précipitent pour copier plutôt que pour guérir.",
  "b-ip-collaboration": "Les entreprises qui possèdent des médicaments complémentaires les testent rarement ensemble, et les données qui pourraient répondre à des questions restent sous clé.",
  "b-knowledge-diffusion": "La diffusion des connaissances est lente : il faut des années pour qu'un résultat prouvé change ce que reçoivent la plupart des patients, et personne ne parvient à suivre la littérature scientifique.",
  "b-manufacturing-cell-therapy": "Les thérapies cellulaires demandent des semaines de fabrication pour un seul patient et coûtent des centaines de milliers de dollars. Les isotopes viennent à manquer.",
  "b-metastasis-biology": "Les métastases causent environ neuf décès par cancer sur dix, mais ne reçoivent qu'une petite fraction des fonds de recherche et presque aucun essai qui leur soit propre.",
  "b-misinformation": "On vend aux patients des traitements non prouvés et on les détourne, par la peur, des traitements qui ont fait leurs preuves.",
  "b-negative-results": "Les essais négatifs, les médicaments qui ont échoué et les programmes abandonnés sont rarement publiés, si bien que les mêmes erreurs se répètent.",
  "b-overdiagnosis": "Détecter plus de cancers n'est pas la même chose que sauver des vies. Le dépistage trouve aussi des cancers qui n'auraient jamais fait de mal à personne, et les traite.",
  "b-palliative": "La plupart des personnes qui meurent d'un cancer dans le monde meurent sans soulagement adéquat de la douleur.",
  "b-patient-voice": "La plupart des patients ne peuvent pas comprendre leurs options, trouver des essais ni faire entendre leur désaccord, si bien que les décisions sont prises à leur place.",
  "b-preclinical-models": "Neuf médicaments anticancéreux sur dix qui fonctionnent chez la souris échouent chez l'humain. Nos modèles en sont la raison.",
  "b-prevention-adoption": "Environ quatre cancers sur dix sont évitables avec des outils que nous possédons déjà : vaccins, lutte contre le tabac, poids, alcool, protection solaire et contrôle des infections.",
  "b-rare-cancers": "Pris ensemble, les cancers rares représentent un cinquième de tous les cancers, mais chacun d'eux, pris isolément, est trop petit pour qu'une entreprise y investisse.",
  "b-real-world-evidence": "Nous ne savons pas de manière fiable ce qui arrive aux patients après l'autorisation, et nous ne pouvons donc pas dire quels médicaments tiennent leurs promesses en pratique.",
  "b-regulatory-fragmentation": "La divergence réglementaire fait qu'un médicament approuvé dans un pays peut mettre des années à en atteindre un autre, ou ne jamais y arriver.",
  "b-reproducibility": "Moins de la moitié des découvertes majeures en biologie du cancer se reproduisent lorsque quelqu'un d'autre essaie.",
  "b-resistance": "Presque toutes les thérapies ciblées cessent de fonctionner en quelques mois à quelques années, à mesure que la tumeur s'adapte.",
  "b-surgery-radiation-innovation": "La chirurgie et la radiothérapie guérissent plus de personnes que les médicaments, mais n'attirent qu'une fraction des investissements en recherche.",
  "b-survivorship": "Des dizaines de millions de personnes vivent après un cancer avec des lésions cardiaques, une infertilité, des seconds cancers et de la peur, et peu de services pour les aider.",
  "b-tme-immunosuppression": "La plupart des tumeurs tiennent le système immunitaire à l'écart ou l'endorment, si bien que l'immunothérapie n'aide qu'une minorité de patients.",
  "b-toxicity-qol": "Les essais mesurent combien de temps les gens vivent, pas comment ils vivent. Les effets secondaires sont sous-déclarés et sous-traités.",
  "b-translational-valley": "La plupart des découvertes académiques meurent avant que quiconque les teste chez l'humain, parce que personne ne finance l'étape intermédiaire.",
  "b-trial-design": "Un essai de phase 3 prend des années et coûte des centaines de millions de dollars, et répond souvent à une question déjà dépassée.",
  "b-trial-diversity": "Les patients âgés, noirs, hispaniques, asiatiques, ruraux, pauvres et atteints de plusieurs maladies sont sous-représentés, si bien que les résultats peuvent ne pas s'appliquer à eux.",
  "b-trial-enrolment": "Moins d'un adulte atteint de cancer sur dix participe à un essai. Les essais ferment par manque de patients, pas par manque d'idées.",
  "b-tumor-heterogeneity": "Une tumeur est en réalité plusieurs tumeurs. Les traitements qui tuent la plupart des cellules laissent les autres repousser, transformées.",
  "b-undruggable-targets": "Les protéines qui alimentent la plupart des cancers, comme MYC, p53 mutée et la plupart des variants de RAS, n'ont toujours pas de bon médicament.",
  "b-workforce": "Le nombre de personnes atteintes de cancer augmente plus vite que les effectifs formés pour les soigner.",
  b7h3: "B7-H3 est une protéine qui freine le système immunitaire, présente sur de nombreuses tumeurs solides et aujourd'hui utilisée comme cible d'adressage pour les ADC, notamment dans le cancer du poumon à petites cellules et le cancer de la prostate.",
  "barts-cancer-institute": "Le plus ancien hôpital de Londres, associé à l'institut du cancer de Queen Mary, connu pour ses recherches sur le cancer du pancréas, les cancers du sang et le microenvironnement tumoral.",
  "base-excision-repair-parp": "Des dizaines de milliers de fois par jour, une seule lettre de l'ADN est oxydée ou chimiquement abîmée. Une petite équipe la découpe et PARP marque l'entaille pour qu'elle soit refermée. Les inhibiteurs de PARP ne se contentent pas d'éteindre PARP ; ils le piègent sur l'ADN, transformant une entaille sans danger en une cassure mortelle lorsque la cellule copie son ADN.",
  "cancer-registries-surveillance": "Les systèmes publics qui recensent chaque diagnostic et chaque décès par cancer dans un pays, et qui nous indiquent si l'incidence et la survie s'améliorent.",
  "cancer-stem-cells-plasticity": "Certaines cellules cancéreuses se comportent comme des cellules souches : elles peuvent reformer toute la tumeur, résister au traitement et changer d'identité. Cette plasticité explique pourquoi les tumeurs récidivent et pourquoi certains cancers du poumon et de la prostate se transforment en un autre type de cancer sous traitement.",
  capivasertib: "Le capivasertib (Truqap) est le premier inhibiteur d'AKT, indiqué dans le cancer du sein avec mutations de la voie PI3K et, depuis 2026, dans le cancer de la prostate avec perte de PTEN.",
  capox: "CAPOX associe la capecitabine orale à l'oxaliplatin comme alternative sous forme de comprimés au FOLFOX. Trois mois de ce traitement après la chirurgie suffisent pour de nombreux cancers du côlon de stade III.",
  "car-nk-macrophage": "Placer le récepteur qui cible le cancer sur des cellules tueuses naturelles ou des macrophages plutôt que sur des lymphocytes T, ce qui pourrait être plus sûr et prêt à l'emploi.",
  "car-t": "Les lymphocytes T du patient sont prélevés, dotés d'un récepteur synthétique qui reconnaît le cancer, multipliés, puis réinjectés comme un médicament vivant.",
  "carbon-ion": "Des particules chargées plus lourdes qui détruisent même les tumeurs résistantes aux radiations, disponibles dans seulement une poignée de centres dans le monde.",
  carboplatin: "Le carboplatin est une chimiothérapie à base de platine qui crée des liaisons croisées dans le DNA ; il fait partie du protocole standard avant chirurgie pour le cancer du sein triple négatif.",
  "cardio-oncology": "Protéger le cœur des traitements contre le cancer, ce qui devient de plus en plus important à mesure que les patients vivent plus longtemps.",
  ccss: "La plus grande étude sur ce qui arrive aux enfants une fois le cancer guéri. En suivant des dizaines de milliers de survivants pendant des décennies, elle a montré que les atteintes cardiaques, les seconds cancers et d'autres effets tardifs étaient fréquents après les traitements anciens, et que les protocoles modernes, plus doux, ont déjà réduit de moitié les décès tardifs.",
  cd19: "CD19 est un marqueur présent sur les lymphocytes B et les cancers des lymphocytes B, et il a été la cible des toutes premières thérapies CAR-T approuvées.",
  cd20: "CD20 est un marqueur des lymphocytes B ; le rituximab dirigé contre lui a été le premier anticorps approuvé contre le cancer, en 1997.",
  cd3: "CD3 est l'interrupteur présent sur chaque lymphocyte T. Les médicaments bispécifiques le saisissent d'un bras et la tumeur de l'autre, forçant le lymphocyte T à attaquer.",
  cd47: "Le signal « ne me mange pas » que les cellules cancéreuses présentent aux macrophages. Le bloquer semblait prometteur, mais le médicament le plus avancé a échoué.",
  "cdk4-6": "CDK4/6 est le moteur qui pousse une cellule à copier son DNA. Le bloquer en plus de l'hormonothérapie a à peu près doublé la durée pendant laquelle le cancer du sein hormonodépendant reste contrôlé.",
  "cdk46-inhibitor": "Des comprimés qui arrêtent le moteur de la division cellulaire, ajoutés à l'hormonothérapie pour le type de cancer du sein le plus fréquent.",
  "cell-cycle-engine-cdks": "La division cellulaire fonctionne selon une horloge faite de cyclines et de leurs kinases (CDKs), chaque paire s'activant dans l'ordre : D-CDK4/6 pour sortir du repos, E-CDK2 pour commencer à copier le DNA, A-CDK2 pour terminer, B-CDK1 pour se diviser. Les cancers accélèrent l'horloge ; les inhibiteurs de CDK la ralentissent.",
  "cell-therapy": "Prélever des cellules immunitaires, les modifier ou les multiplier, puis les réinjecter comme un médicament vivant.",
  "cell-therapy-roadmap": "De la guérison de certaines leucémies en 2017 à la première CAR-T contre les tumeurs solides, jusqu'à la perspective de fabriquer des CAR-T directement dans le corps par une injection.",
  cemiplimab: "Un bloqueur de PD-1 qui est le traitement standard du carcinome épidermoïde cutané avancé et qui, en 2025, est devenu la première immunothérapie adjuvante pour ce cancer.",
  cetuximab: "Un anticorps qui bloque le récepteur de croissance EGFR. Il est efficace dans les cancers de l'intestin dont le gène RAS est normal, surtout ceux du côté gauche, et il est un partenaire clé de l'association ciblant BRAF.",
  "cgas-sting": "cGAS-STING est l'alarme de la cellule face à du DNA qui se trouve au mauvais endroit. La radiothérapie, la chimiothérapie et les ADC répandent du DNA dans le cytoplasme ; cGAS le détecte, STING déclenche l'alarme et l'interféron appelle le système immunitaire.",
  cgp: "Séquencer des centaines de gènes du cancer en une seule fois à partir d'une biopsie pour trouver les mutations qu'un médicament peut cibler.",
  "checkmate-067": "L'essai avec le plus long suivi en immunothérapie : environ la moitié des patients sous l'association sont en vie à 10 ans.",
  "checkpoint-inhibitor": "Des anticorps qui relâchent les freins des cellules immunitaires pour qu'elles puissent attaquer le cancer. Ils guérissent une minorité de patients dans de nombreux cancers, ce que la chimiothérapie fait rarement.",
  chemoprevention: "Des médicaments ou une chirurgie pour les personnes présentant un risque hérité élevé, avant l'apparition de tout cancer.",
  chemoradiation: "Une radiothérapie administrée en même temps que la chimiothérapie, ce qui rend la radiothérapie plus efficace. C'est le traitement curatif de nombreux cancers qui ne peuvent pas ou ne doivent pas être opérés.",
  chemotherapy: "Des médicaments qui tuent les cellules qui se divisent rapidement. Toujours la colonne vertébrale de nombreuses guérisons, et désormais l'ogive placée à l'intérieur de médicaments plus intelligents.",
  "childrens-oncology-group": "Le Children's Oncology Group est la plus grande organisation d'essais cliniques en cancérologie pédiatrique au monde ; la plupart des enfants atteints de cancer en Amérique du Nord sont traités dans le cadre d'un protocole du COG ou selon celui-ci.",
  chop: "L'hôpital pour enfants où la thérapie CAR-T a guéri pour la première fois la leucémie d'un enfant (Emily Whitehead, 2012) et où la génomique du neuroblastome a identifié ALK.",
  "basket-umbrella-platform": "Des schémas d'essais qui testent un médicament dans de nombreux cancers (basket), plusieurs médicaments dans un seul cancer (umbrella), ou qui ajoutent des bras au fil du temps (plateforme).",
  "bbb-focused-ultrasound": "Des ondes sonores associées à des microbulles ouvrent brièvement la barrière protectrice du cerveau pour que la chimiothérapie ou les anticorps puissent atteindre la tumeur.",
  "bcg-and-intravesical-therapy": "Traiter le cancer de la vessie à un stade précoce en introduisant le médicament directement dans la vessie par une sonde, ce qui épargne le reste du corps.",
  bcl2: "Une protéine qui empêche les cellules de s'autodétruire. Le venetoclax supprime cette protection et a transformé le traitement de la leucémie.",
  bcma: "BCMA est un récepteur de survie présent sur les plasmocytes, et la cible qui a permis aux CAR-T et aux anticorps bispécifiques de fonctionner dans le myélome multiple.",
  "bcr-abl": "La fusion qui définit la leucémie myéloïde chronique et un quart des leucémies aiguës lymphoblastiques de l'adulte ; le premier moteur du cancer jamais éteint par un comprimé.",
  belzutifan: "Le belzutifan est le premier inhibiteur de HIF-2α, issu d'une biologie récompensée par un prix Nobel, et il est désormais approuvé après une chirurgie du cancer du rein en association avec le pembrolizumab.",
  bevacizumab: "Le premier médicament à priver les tumeurs de vaisseaux sanguins. Approuvé en 2004 pour le cancer de l'intestin, il reste un partenaire standard de la chimiothérapie dans de nombreux cancers et c'est l'ajout qui rend les comprimés des lignes tardives plus efficaces.",
  "bispecific-adc": "Un ADC bispécifique est un ADC dont l'anticorps s'accroche à deux protéines différentes de la cellule cancéreuse, ce qui lui permet de mieux se fixer à la tumeur et moins aux tissus sains.",
  "bispecific-antibody": "Un anticorps bispécifique est un seul anticorps doté de deux bras de préhension différents, ce qui lui permet de bloquer deux cibles à la fois ou d'attirer une cellule immunitaire sur une cellule cancéreuse.",
  blinatumomab: "Le blinatumomab a été le premier engageur de lymphocytes T (2014), et il est désormais administré aux enfants et aux adultes atteints de leucémie même en rémission, parce qu'il améliore la survie.",
  "blood-brain-barrier": "Le joint étanche qui entoure les vaisseaux sanguins du cerveau et tient la plupart des médicaments à l'écart, l'une des deux principales raisons pour lesquelles le cancer du cerveau est si difficile à traiter.",
  "blood-brain-barrier-metastasis": "Les vaisseaux sanguins du cerveau sont hermétiquement fermés et équipés de pompes qui expulsent la plupart des médicaments. Cela protège le cerveau des poisons, mais aussi de la chimiothérapie et des anticorps. Les cellules cancéreuses qui parviennent tout de même à se faufiler recrutent les propres cellules de soutien du cerveau, les astrocytes, pour les nourrir et les protéger.",
  bms: "Pionnier des inhibiteurs de points de contrôle (Opdivo, Yervoy), qui mise aujourd'hui sur le premier ADC bispécifique réussi et sur les radiopharmaceutiques alpha.",
  bortezomib: "Le bortezomib a été le premier inhibiteur du protéasome : il bloque la machine de recyclage des protéines de la cellule, ce que les plasmocytes, véritables usines à anticorps, ne peuvent pas tolérer.",
  brachytherapy: "La curiethérapie place une source radioactive directement à l'intérieur de la tumeur ou juste à côté.",
  braf: "BRAF est une kinase de signalisation mutée dans la moitié des mélanomes ; son blocage par deux médicaments à la fois est devenu un modèle pour la thérapie ciblée.",
  brca: "Des gènes de réparation de l'ADN. Hériter d'une copie défectueuse augmente le risque de cancer du sein et de l'ovaire, mais les tumeurs qui les perdent deviennent particulièrement vulnérables aux inhibiteurs de PARP et au platine.",
  "brentuximab-vedotin": "L'ADC qui a donné sa crédibilité au domaine moderne (2011), pour le lymphome de Hodgkin et les lymphomes CD30+.",
  "broad-institute": "Le Broad Institute est la puissance de la génomique derrière DepMap, le co-développement de cBioPortal et la Cancer Cell Line Encyclopedia.",
  btk: "L'enzyme de signalisation que les cancers des lymphocytes B utilisent pour survivre. Son blocage a transformé la leucémie lymphoïde chronique en une maladie contrôlée par un comprimé quotidien.",
  "burkitt-lymphoma": "Le lymphome de Burkitt est la tumeur humaine à la croissance la plus rapide, entraînée par un seul réarrangement qui active le gène MYC. Cette vitesse le rend extrêmement sensible à la chimiothérapie : des cures courtes et intensives, désormais avec l'anticorps rituximab, guérissent la grande majorité des enfants dans les pays bien dotés en ressources. Il reste à apporter la même guérison aux enfants africains, qui représentent la majorité des cas.",
  cabozantinib: "Un comprimé qui bloque à la fois la croissance des vaisseaux sanguins et la voie d'échappement MET, utilisé dans les cancers du rein, du foie, de la thyroïde et, depuis 2025, les cancers neuroendocrines.",
  cachexia: "Une perte sévère de poids et de muscle dans le cancer avancé que le simple fait de manger davantage ne peut pas inverser. Elle touche jusqu'à 8 patients sur 10 atteints d'une maladie avancée et contribue à un cinquième des décès par cancer.",
  "cachexia-appetite-pharmacotherapy": "La pharmacothérapie de la cachexie regroupe trois approches médicamenteuses de la fonte liée au cancer : un nouvel anticorps qui bloque l'hormone supprimant l'appétit, un imitateur de l'hormone de l'appétit approuvé uniquement au Japon, et un vieux comprimé très bon marché. Aucun n'est encore le standard partout ; tous font mieux que ce qui existait avant.",
  "caf-activation-desmoplasia": "Les tumeurs recrutent les cellules de réparation de l'organisme, les fibroblastes, et les maintiennent pour toujours en mode cicatrisation. Le tissu cicatriciel qu'ils déposent (desmoplasie) écrase les vaisseaux sanguins jusqu'à les fermer, tient les cellules immunitaires à l'écart, rigidifie le tissu d'une manière qui, en elle-même, incite les cellules cancéreuses à croître, et c'est la raison pour laquelle le cancer du pancréas est si difficile à traiter.",
  camrelizumab: "L'un des bloqueurs de PD-1 les plus utilisés en Chine, approuvé là-bas pour les cancers de l'œsophage, du foie, du poumon et d'autres cancers ; non approuvé aux États-Unis.",
  "cams-cancer-hospital": "Le CAMS Cancer Hospital est le centre national du cancer de la Chine, qui mène des essais de niveau réglementaire sur des ADC et des anticorps PD-1 produits localement.",
  "cancer-immunity-cycle": "Sept étapes que le système immunitaire doit accomplir pour tuer une tumeur : libération des antigènes, capture par les cellules dendritiques, activation des lymphocytes T dans les ganglions lymphatiques, déplacement, entrée dans la tumeur, reconnaissance et destruction. Chaque immunothérapie agit sur une étape ; chaque échappement en bloque une.",
  "cancer-metabolism": "Les cellules cancéreuses reprogramment leur façon de se nourrir. Elles brûlent le glucose de manière inefficace mais rapide (l'effet Warburg), se gavent de glutamine et de graisses, et fabriquent les nucléotides et les lipides nécessaires pour se diviser. C'est pour cela que l'examen FDG PET fonctionne, et que le métabolisme est une cible thérapeutique.",
  chordoma: "Le chordome est un cancer des os à croissance lente de la base du crâne et de la colonne vertébrale, issu de cellules embryonnaires résiduelles de la notochorde. Une chirurgie complète suivie d'une radiothérapie à haute dose par protons ou ions carbone contrôle la plupart des tumeurs, et toute la maladie dépend d'un seul facteur de transcription, brachyury, que des vaccins et des dégradeurs tentent aujourd'hui de cibler.",
  "chromosomal-instability": "La plupart des cancers ont un nombre anormal de chromosomes et continuent de les remanier à chaque division. Ce chaos alimente l'évolution et la résistance aux médicaments, mais il met aussi la cellule sous tension et peut déclencher des alertes immunitaires, une arme à double tranchant que les chercheurs tentent d'exploiter.",
  "ciltacabtagene-autoleucel": "Ciltacabtagene autoleucel est une thérapie CAR-T anti-BCMA administrée en une seule fois pour le myélome qui, dans l'essai CARTITUDE-4, a réduit le risque de décès d'environ 45 % par rapport aux traitements standard.",
  "circulate-japan": "Le programme national du Japon évalue si une analyse de sang après la chirurgie devrait décider qui reçoit une chimiothérapie, et si traiter tôt un test positif est bénéfique.",
  cisplatin: "Cisplatin est la chimiothérapie au platine d'origine, découverte par hasard en 1965 ; elle guérit le cancer du testicule et rend la radiothérapie plus efficace dans le cancer du col de l'utérus et les cancers de la tête et du cou.",
  "city-of-hope": "Centre de cancérologie de Los Angeles où ont été mis au point l'insuline synthétique et les anticorps humanisés ; un leader de la fabrication de CAR-T.",
  "cldn18-2": "Une protéine des jonctions serrées, normalement cachée dans la paroi de l'estomac, qui devient exposée dans les cancers de l'estomac et du pancréas.",
  "clinicaltrials-gov": "ClinicalTrials.gov est le registre de référence des essais cliniques. Chaque essai présenté sur ce site renvoie à sa fiche.",
  "clonal-evolution": "Une tumeur est une population qui évolue par sélection naturelle. Le traitement tue les cellules sensibles et sélectionne les autres, c'est pourquoi la résistance est la règle ; mesurer la population survivante (MRD) et adapter le traitement est la contre-stratégie.",
  cmml: "Ce sont des cancers de la moelle osseuse qui se comportent en partie comme une myélodysplasie (cellules sanguines mal fabriquées) et en partie comme une maladie proliférative (trop de monocytes ou de plaquettes). Les médicaments qui reprogramment le contrôle des gènes de la moelle (agents hypométhylants) aident de nombreux patients, une greffe de cellules souches peut guérir les personnes en assez bonne forme, et les mutations motrices que l'on cartographie aujourd'hui orientent vers des médicaments ciblés.",
  "cold-spring-harbor": "Centre de recherche fondamentale sur le cancer où la biologie de RAS, les suppresseurs de tumeurs et les modèles d'organoïdes ont progressé.",
  "cold-vs-hot": "Les tumeurs « chaudes » sont remplies de cellules immunitaires et répondent à l'immunothérapie ; les tumeurs « froides » ont tenu le système immunitaire à l'écart.",
  "colorectal-screening": "Trouver et retirer les polypes avant qu'ils ne deviennent un cancer. La coloscopie prévient le cancer ; les tests sur les selles et le sang le détectent tôt et permettent de dépister davantage de personnes.",
  "companion-diagnostic": "Le test qui détermine si un médicament précis vous convient, approuvé en même temps que le médicament.",
  "complement-in-cancer": "Le complément est une cascade de protéines du sang qui perce des trous dans ce que les anticorps ont marqué et appelle des cellules inflammatoires. Les anticorps thérapeutiques comme le rituximab s'en servent pour tuer les cellules cancéreuses ; les tumeurs se défendent avec des boucliers (CD46, CD55, CD59), et les sous-produits de la cascade elle-même (C5a) peuvent recruter les cellules myéloïdes qui protègent la tumeur.",
  cps: "Un score PD-L1 qui compte ensemble les cellules tumorales et les cellules immunitaires marquées.",
  craniopharyngioma: "Le craniopharyngiome est une tumeur bénigne mais destructrice qui se développe à partir de vestiges embryonnaires à côté de l'hypophyse et de l'hypothalamus. La chirurgie, ou une chirurgie limitée associée à une radiothérapie, guérit la plupart des personnes, mais le prix peut être un déficit hormonal à vie et une obésité sévère. La forme de l'adulte (papillaire) porte une mutation de BRAF et régresse de façon spectaculaire sous inhibiteurs de BRAF et de MEK, son premier traitement médicamenteux.",
  "crispr-screens": "Inactiver chaque gène, un par un, dans des cellules cancéreuses pour découvrir ceux dont elles ne peuvent pas se passer.",
  crs: "Un déferlement de signaux inflammatoires lorsque les cellules immunitaires sont activées en masse, provoquant de la fièvre, une baisse de la tension artérielle et parfois une défaillance d'organes.",
  cruk: "Cancer Research UK est la plus grande association caritative indépendante de recherche sur le cancer au monde ; elle finance le Crick, l'ICR, Manchester, Cambridge, ainsi que les essais STAMPEDE et TRACERx.",
  "cruk-cambridge-centre": "Le partenariat de Cambridge contre le cancer entre l'université et Addenbrooke's, célèbre pour la génomique du cancer du sein, la biopsie liquide et la détection précoce du cancer de l'œsophage.",
  csf1r: "Le récepteur dont dépendent les macrophages ; le bloquer fait régresser la tumeur ténosynoviale à cellules géantes (une tumeur dépendante de CSF1) et élimine les macrophages qui soutiennent la tumeur, même si ce dernier effet n'a pas encore aidé les patients atteints de cancers courants.",
  ct: "Un scanner (CT) est une radiographie 3D rapide qui montre la taille et la forme des tumeurs et si elles se sont propagées.",
  ctdna: "L'ADN tumoral circulant (ctDNA) est constitué de fragments d'ADN libérés par les cellules tumorales dans le sang, détectables par un séquençage sensible.",
  ctla4: "Le premier frein immunitaire jamais ciblé contre le cancer ; le relâcher a valu un prix Nobel et guérit une fraction des mélanomes.",
  "cure-paths": "Trois façons différentes pour qu'un cancer cesse de tuer quelqu'un : l'arrêter avant qu'il ne commence, éliminer jusqu'à la dernière cellule, ou le tenir en échec toute la vie. Chacune nécessite une technologie différente.",
  "curie-nki-eortc": "L'EORTC est l'organisation académique européenne des essais cliniques en cancérologie et mène des essais qui changent la pratique depuis 1962.",
  cyclophosphamide: "L'un des médicaments de chimiothérapie les plus utilisés : il fait partie du CHOP pour le lymphome, de l'AC pour le cancer du sein, du VAC pour les sarcomes de l'enfant, et sert à préparer les patients aux CAR-T et à la greffe.",
  "cytokine-therapy": "La thérapie par cytokines administre comme médicaments des protéines de signalisation immunitaire. L'interleukine-2 à haute dose a été la première immunothérapie à guérir certains mélanomes, au prix d'une grande toxicité.",
  "cytotoxic-chemotherapy": "Les médicaments de chimiothérapie cytotoxique tuent les cellules qui se divisent rapidement. Ils restent curatifs dans le cancer du testicule, le lymphome, la leucémie et de nombreux cancers à un stade précoce, et ils constituent l'ogive contenue dans les ADC.",
  "early-detection-roadmap": "Des mammographies et coloscopies à une simple prise de sang qui pourrait dépister des dizaines de cancers, avec une première décision de la FDA imminente.",
  "ecog-acrin": "Groupe coopératif américain qui associe un groupe de thérapie à un groupe d'imagerie ; son essai E1910 a fait entrer le blinatumomab dans le traitement de première ligne de la leucémie.",
  "efflux-pump": "Pompes moléculaires présentes sur les cellules cancéreuses qui expulsent la chimiothérapie et les charges utiles des ADC avant qu'elles ne puissent agir.",
  efs: "Dans le cancer à un stade précoce : combien de temps les patients restent sans récidive, sans progression ni décès.",
  egfr: "Un récepteur de croissance muté dans certains cancers du poumon et surproduit dans d'autres ; le premier grand succès des comprimés ciblés.",
  "eli-lilly": "Eli Lilly fabrique Verzenio et Retevmo, ainsi que le SERD oral imlunestrant et l'inhibiteur de BTK pirtobrutinib.",
  ema: "L'agence de l'Union européenne dont le Comité des médicaments à usage humain recommande les autorisations de mise sur le marché des médicaments contre le cancer dans tous les États membres.",
  emt: "Comment une cellule cancéreuse change de forme pour migrer et résister aux médicaments. Des facteurs de transcription comme ZEB1 et SNAIL relâchent la cellule, activent des pompes qui expulsent la chimiothérapie et la dissimulent au système immunitaire.",
  encorafenib: "Encorafenib est un inhibiteur de BRAF qui, avec le cetuximab et la chimiothérapie, est devenu en 2026 le traitement standard de première ligne du cancer colorectal avec mutation BRAF.",
  "endocrine-therapy": "Des comprimés qui bloquent ou suppriment la signalisation des œstrogènes, pilier du traitement du cancer du sein hormonodépendant depuis 50 ans.",
  "endoscopic-resection": "Retirer des cancers très précoces de l'œsophage ou de l'estomac par l'intérieur, à l'aide d'un endoscope, de façon à conserver l'organe intact.",
  "energy-balance": "Le terme générique que les chercheurs utilisent pour l'effet combiné de ce que vous mangez, de votre niveau d'activité physique et de votre quantité de graisse corporelle. C'est le cadre qui relie la recherche sur l'alimentation, l'exercice et l'obésité au cancer.",
  "enfortumab-vedotin": "Enfortumab vedotin est un ADC dirigé contre Nectin-4 qui, associé au pembrolizumab, a presque doublé la survie dans le cancer de la vessie avancé.",
  enzalutamide: "Le bloqueur du récepteur des androgènes le plus utilisé, approuvé à tous les stades du cancer de la prostate avancé, y compris en cas de PSA en hausse après la chirurgie.",
  epcoritamab: "Epcoritamab est une injection sous la peau qui attire les cellules T vers les cellules du lymphome ; il est approuvé pour le lymphome à grandes cellules B et le lymphome folliculaire en rechute, et progresse vers la première ligne.",
  ependymoma: "Les épendymomes se développent à partir des cellules qui tapissent les espaces remplis de liquide du cerveau et de la moelle épinière. L'ablation complète de la tumeur, suivie d'une radiothérapie ciblée avec précision, guérit de nombreux enfants ; la tumeur a été classée en groupes moléculaires qui se comportent très différemment, et le travail du domaine consiste à adapter l'intensité du traitement à chaque groupe et à trouver les premiers médicaments efficaces.",
  "epigenetic-drugs": "Des médicaments qui modifient la façon dont les gènes sont activés et désactivés, sans modifier le DNA lui-même.",
  "epigenetic-reprogramming": "Le cancer ne modifie pas seulement ses gènes, mais aussi la façon dont ils sont lus : des marques chimiques sur le DNA et les histones font taire les gardiens et réveillent des programmes de croissance. Contrairement aux mutations, ces changements sont réversibles, et c'est là tout l'espoir des médicaments épigénétiques.",
  "epithelioid-sarcoma": "Le sarcome épithélioïde est un cancer rare des tissus mous qui a perdu un gène frein appelé SMARCB1, ce qui le rend dépendant de l'enzyme EZH2. La chirurgie guérit les tumeurs localisées, et l'inhibiteur d'EZH2 tazemetostat, premier médicament épigénétique approuvé pour une tumeur solide, permet un contrôle durable de la maladie dans certains cas avancés.",
  "er-signaling": "Dans le cancer du sein hormonopositif, l'œstrogène se fixe à son récepteur, qui active des gènes faisant se diviser la cellule. Chaque traitement endocrinien coupe cette chaîne à un endroit ou à un autre.",
  "erasmus-mc": "Le centre anticancéreux intégré de Rotterdam, accrédité par l'OECI, où la thérapie par radionucléides ciblant les récepteurs peptidiques au lutétium-177 a été mise au point pour la première fois et où les plus grands essais de dépistage d'Europe ont été dirigés.",
  esmo: "L'ESMO est la société européenne d'oncologie, connue pour son Congrès chaque automne et pour l'échelle ESMO-MCBS qui évalue la valeur des nouveaux médicaments.",
  "essen-wtz": "L'un des centres anticancéreux les plus anciens et les plus grands d'Allemagne, qui abrite le Centre de protonthérapie d'Allemagne de l'Ouest et un programme de premier plan en mélanome et en théranostique.",
  estro: "La société européenne de radiothérapie oncologique, qui organise le congrès ESTRO, dirige une école formant une grande partie du personnel de radiothérapie dans le monde et établit les normes qui sous-tendent la curiethérapie et la radiothérapie adaptative.",
  "estrogen-receptor": "L'interrupteur hormonal qui alimente la plupart des cancers du sein. Le bloquer ou le détruire est la thérapie ciblée la plus ancienne et la plus efficace.",
  etoposide: "Etoposide est une chimiothérapie issue de la plante podophylle, essentielle pour guérir le cancer du testicule (BEP), traiter le cancer du poumon à petites cellules, les lymphomes, les sarcomes de l'enfant et les leucémies, et utilisée dans le conditionnement avant greffe.",
  everolimus: "Un comprimé qui bloque mTOR, qui a doublé le temps sans progression avec exemestane en 2012 et qui est aujourd'hui associé au SERD oral giredestrant.",
  "exercise-oncology": "Un exercice physique structuré pendant et après le traitement, dont l'essai CHALLENGE a montré qu'il améliore la survie dans le cancer du côlon.",
  ezh2: "EZH2 est une enzyme qui fait taire des gènes. Le premier médicament dirigé contre elle a traité un sarcome rare et certains lymphomes jusqu'à son retrait en 2026 pour avoir provoqué des seconds cancers du sang.",
  fap: "FAP est une protéine présente sur les cellules de soutien qui entourent de nombreuses tumeurs, ce qui fait qu'elle révèle presque n'importe quel cancer solide sur un PET scan.",
  "fapi-pet": "La TEP FAPI est un examen TEP qui fait ressortir l'échafaudage qui entoure presque toutes les tumeurs solides, y compris des cancers que l'examen standard au sucre ne détecte pas.",
  "fda-oce": "Le pôle d'oncologie du régulateur américain, qui approuve les médicaments contre le cancer, gère l'approbation accélérée et le Project Orbis, et pousse à une meilleure recherche de dose via le Project Optimus.",
  "fdg-pet": "La TEP au FDG est l'examen TEP standard. Un sucre radioactif montre quels tissus consomment rapidement du glucose, ce que font la plupart des cancers.",
  fgfr2: "FGFR2 est un récepteur de croissance qui est fusionné dans le cancer des voies biliaires et surproduit dans le cancer de l'estomac.",
  "first-line": "La première ligne est le premier traitement d'un cancer avancé ; la deuxième ligne est celui qui vient après son échec, et ainsi de suite.",
  flt3: "FLT3 est une kinase mutée dans environ un tiers des leucémies aiguës myéloïdes, où l'ajout d'un inhibiteur à la chimiothérapie améliore la survie.",
  "fluorescence-guided-surgery": "Injecter un colorant qui fait briller la tumeur pour que le chirurgien voie exactement où couper.",
  fluorouracil: "La chimiothérapie de 1957 qui reste le pilier du traitement des cancers de l'intestin, de l'estomac, du pancréas, de l'anus, de la tête et du cou et du sein, et qui s'utilise en crème pour les lésions précancéreuses de la peau.",
  folfox: "FOLFOX est la combinaison de chimiothérapie de référence pour le cancer de l'intestin, utilisée après la chirurgie dans un but curatif et, dans la maladie avancée, comme socle auquel on ajoute les traitements ciblés.",
  folr1: "Le récepteur alpha du folate est un récepteur de vitamine que les cellules du cancer de l'ovaire portent en grand nombre, utilisé comme point d'ancrage pour l'ADC mirvetuximab.",
  "francis-crick": "Le Francis Crick Institute est le plus grand institut de recherche biomédicale d'Europe et le foyer des études TRACERx sur l'évolution des tumeurs (Swanton).",
  "fred-hutch": "Berceau de la greffe de moelle osseuse (Thomas, Nobel 1990) et pionnier des CAR-T (Riddell).",
  "frontier-2035": "L'oncologie radicale est une carte d'horizon des idées les plus audacieuses en cancérologie, classées selon leur proximité d'un impact réel, avec la raison pour laquelle chacune pourrait ne jamais aboutir.",
  "functional-drug-testing": "Cultiver les propres cellules cancéreuses d'un patient dans une boîte et tester directement les médicaments sur elles, au lieu de deviner à partir de la génétique.",
  gallbladder: "Le cancer de la vésicule biliaire est un cancer de la poche qui stocke la bile sous le foie, le plus souvent découvert par hasard lorsque la vésicule est retirée pour des calculs. Détecté tôt, une seconde opération pour nettoyer le lit hépatique et les ganglions peut le guérir ; dans la maladie avancée, la chimiothérapie s'accompagne désormais d'une immunothérapie, et les anticorps dirigés contre HER2 aident le sous-groupe dont les tumeurs surexpriment HER2.",
  galleri: "Un test sanguin de dépistage de plus de 50 cancers à la fois, soumis à la FDA en septembre 2026.",
  "gardasil-9": "Un vaccin contre neuf types de HPV qui prévient environ 90 % des cancers du col de l'utérus, et qui fonctionne désormais avec une seule dose.",
  gd2: "GD2 est une molécule de sucre et de graisse présente à la surface des cellules de neuroblastome (et de certaines autres tumeurs de l'enfant et de l'adulte), quasiment absente des tissus normaux à l'exception des nerfs, ce qui explique pourquoi les médicaments anti-GD2 provoquent des douleurs.",
  "gemcitabine-cisplatin": "Gemcitabine plus cisplatin est le socle de la chimiothérapie du cancer des voies biliaires depuis 2010 et s'administre désormais avec une immunothérapie.",
  "gene-fusion": "Une fusion de gènes, c'est deux gènes cassés puis soudés ensemble, créant une protéine hybride capable de provoquer un cancer. Les cancers dus à une fusion sont souvent extrêmement sensibles aux médicaments.",
  "geriatric-assessment": "L'évaluation gériatrique est un bilan structuré de la forme physique, de la mémoire et du soutien dont dispose un patient âgé, qui prédit la tolérance au traitement mieux que l'âge.",
  "germline-testing": "Un test de l'ADN avec lequel vous êtes né, pour rechercher des gènes de risque hérités tels que BRCA ou le syndrome de Lynch.",
  "germline-vs-somatic": "Les mutations germinales sont héritées et présentes dans toutes les cellules ; les mutations somatiques apparaissent uniquement dans la tumeur.",
  gilead: "Gilead détient Trodelvy (via le rachat d'Immunomedics pour 21 milliards de dollars) et la franchise CAR-T de Kite.",
  "glioma-car-t": "Des cellules immunitaires modifiées, administrées directement dans le cerveau ou le liquide céphalo-rachidien. Certains enfants atteints de gliome diffus de la ligne médiane, une tumeur du tronc cérébral sans traitement curatif, ont eu des réponses spectaculaires, bien que temporaires.",
  "global-oncology-access": "Soixante-dix pour cent des décès par cancer surviennent dans les pays à revenu faible ou intermédiaire, où les appareils de radiothérapie, les pathologistes, les médicaments essentiels et les soins palliatifs sont rares. L'oncologie mondiale travaille à des soins abordables et adaptés, ainsi qu'aux systèmes pour les délivrer.",
  glofitamab: "Glofitamab est un anticorps bispécifique à durée fixe pour le lymphome à grandes cellules B, avec un bénéfice de survie globale (OS) lorsqu'il est associé à la chimiothérapie.",
  "glp1-agonists-cancer-risk": "Les agonistes du GLP-1, les nouvelles injections amaigrissantes, réduisent le poids de 15 à 20 %. Les premières données observationnelles suggèrent moins de cancers liés à l'obésité chez les personnes qui les prennent, mais aucun essai n'a encore évalué le cancer comme critère de jugement.",
  "glutamine-metabolism": "Après le glucose, la glutamine est l'aliment préféré de la tumeur. Elle alimente le cycle énergétique, fournit l'azote nécessaire à la fabrication des lettres de l'ADN et produit l'antioxydant glutathion. Les cancers pilotés par MYC et KRAS en consomment tellement qu'ils affament les cellules T voisines.",
  "gog-foundation": "L'organisation américaine d'essais cliniques en oncologie gynécologique dont les essais de la série GOG-3000, menés avec l'industrie, ont fait entrer l'immunothérapie dans le cancer de l'endomètre et du col de l'utérus.",
  "guardant-health": "Leader de la biopsie liquide : Guardant360 pour le génotypage, Reveal pour la MRD et Shield pour le dépistage.",
  "guardant360-cdx": "Un test sanguin qui lit les mutations d'une tumeur sans biopsie tissulaire et qui constitue la porte d'entrée approuvée par la FDA vers plusieurs traitements ciblés.",
  "gustave-roussy": "Gustave Roussy est le premier centre de lutte contre le cancer en Europe, berceau de l'échelle ESMO-MCBS et à la tête de grands essais sur les ADC et l'immunothérapie.",
  "hazard-ratio": "Un hazard ratio (rapport de risques) est un nombre qui compare la fréquence des événements indésirables dans deux groupes. Un HR de 0,5 signifie que le risque est divisé par deux à tout moment.",
  "heidelberg-nct": "Heidelberg est la capitale allemande de la recherche sur le cancer, siège du DKFZ (le plus grand institut de recherche sur le cancer d'Allemagne) et du NCT, et berceau du FAPI PET et du classificateur de méthylation des tumeurs cérébrales.",
  hengrui: "Jiangsu Hengrui est le plus grand laboratoire pharmaceutique d'oncologie de Chine, fabricant du pyrotinib et de l'ADC anti-HER2 trastuzumab rezetecan, et l'un des plus grands concédants de licences d'actifs chinois à l'étranger.",
  her2: "Un récepteur de signaux de croissance. Certains cancers en produisent beaucoup trop, et les médicaments qui le bloquent ou s'en servent comme point d'ancrage ont changé la donne pour ces cancers.",
  "her2-low": "Des tumeurs qui présentent un peu de HER2 (IHC 1+ ou 2+ sans amplification), ou seulement une trace (ultralow), que les anciens médicaments anti-HER2 ignoraient mais qu'Enhertu peut attaquer.",
  her3: "HER3 est un cousin de HER2 que les cancers utilisent comme voie de secours lorsque HER2 ou EGFR sont bloqués.",
  "hereditary-cancer-syndromes": "Environ 5 à 10 % des cancers sont dus à une anomalie génétique héréditaire. Reconnaître ces syndromes (BRCA, Lynch, Li-Fraumeni, VHL, MEN, FAP, rétinoblastome et des dizaines d'autres) change le dépistage, la chirurgie et le traitement pour le patient et ses proches.",
  "hif-vhl": "La voie VHL/HIF est le mécanisme par lequel les cellules détectent l'oxygène (prix Nobel 2019). VHL détruit HIF lorsque l'oxygène est présent. Les cancers du rein perdent VHL, si bien que HIF-2α reste allumé en permanence et stimule la formation de vaisseaux sanguins et la prolifération.",
  hif2a: "Un interrupteur central que les cellules du cancer du rein laissent allumé en permanence lorsqu'elles perdent le gène VHL ; le belzutifan le bloque.",
  "hifu-histotripsy": "Détruire des tumeurs depuis l'extérieur du corps grâce à des ondes sonores très finement focalisées, en utilisant soit la chaleur, soit des bulles microscopiques.",
  hipec: "Rincer la cavité abdominale avec une chimiothérapie chauffée pendant l'opération afin de tuer les dépôts péritonéaux microscopiques.",
  histiocytoses: "Les histiocytoses sont des maladies dans lesquelles des cellules immunitaires chargées du nettoyage s'accumulent dans les os, le cœur, le cerveau, les reins et la peau. On les traitait autrefois comme des maladies inflammatoires, avec des corticoïdes et de l'interféron. La découverte que la plupart portent des mutations dans la même voie de croissance que le mélanome en a fait des cancers ciblables : les comprimés inhibiteurs de BRAF et de MEK produisent aujourd'hui une réponse chez presque tous les patients traités.",
  "histopathology-ihc": "L'histopathologie consiste à examiner les cellules cancéreuses au microscope, et l'immunohistochimie les colore pour révéler des protéines spécifiques. Ensemble, elles restent le fondement de tout diagnostic.",
  "hiv-associated-lymphoma": "Les personnes vivant avec le HIV ont un risque accru de lymphomes agressifs, favorisés par l'immunosuppression et par des virus tels que le virus d'Epstein-Barr. La transformation des deux dernières décennies est que, en poursuivant le traitement antirétroviral pendant la prise en charge, ces lymphomes sont traités avec les mêmes protocoles de chimiothérapie à pleine dose et d'anticorps que chez n'importe qui d'autre, avec des chances de guérison similaires.",
  "homologous-recombination-repair": "Une cassure des deux brins de l'ADN est la lésion la plus dangereuse à laquelle une cellule est confrontée. Deux équipes se disputent la réparation : la recombinaison homologue copie la bonne réponse sur le chromosome sœur (précise, mais nécessite BRCA), tandis que la jonction des extrémités recolle simplement les bouts (rapide, mais bâclée). L'équipe qui l'emporte détermine si les inhibiteurs de PARP et la radiothérapie tuent la cellule.",
  hormonal: "Couper l'apport des hormones dont certains cancers, en particulier ceux du sein et de la prostate, ont besoin pour se développer.",
  "hospital-clinic-barcelona": "L'hôpital universitaire de Barcelone, berceau du système de stadification BCLC du cancer du foie et du premier CAR-T académique européen, et à la pointe de la génomique du cancer du sein et des lymphomes.",
  "hpv-testing": "Un prélèvement par écouvillon analysé pour détecter le virus responsable du cancer du col de l'utérus, plus précis que le frottis et réalisable à domicile.",
  "hpv-vaccine": "Des vaccins qui préviennent les infections virales à l'origine des cancers du col de l'utérus, de la gorge, de l'anus et du foie. L'intervention anticancéreuse la plus efficace jamais créée.",
  hrd: "Une tumeur incapable de réparer correctement les cassures double brin de l'ADN, généralement à cause de la perte de BRCA ou d'un gène apparenté.",
  iarc: "L'IARC est l'agence de la WHO consacrée au cancer, chargée des statistiques mondiales sur le cancer (GLOBOCAN), de la classification des cancérogènes et de la recherche en prévention.",
  ibrutinib: "Le comprimé qui a mis fin à la chimiothérapie pour la plupart des CLL. Il bloque le signal de survie dont dépendent les lymphocytes B, et il a été le premier médicament à surpasser la chimio-immunothérapie dans presque toutes les situations de CLL.",
  icans: "L'ICANS désigne une confusion, des difficultés d'élocution et, rarement, des crises convulsives après un traitement par CAR-T ou par anticorps bispécifique.",
  "icr-london": "A découvert plus de médicaments anticancéreux que toute autre institution académique, dont l'abiraterone et l'utilisation clinique des inhibiteurs de PARP.",
  idh: "Une enzyme du métabolisme dont la forme mutée produit une molécule qui brouille la lecture des gènes ; la bloquer ralentit les tumeurs cérébrales et les leucémies.",
  ifosfamide: "Ifosfamide est une chimiothérapie alkylante associée à la doxorubicin dans les sarcomes et à l'etoposide dans le sarcome d'Ewing, administrée avec un médicament qui protège la vessie.",
  imaging: "L'imagerie regroupe les moyens de voir le cancer à l'intérieur du corps sans ouvrir, des radiographies aux traceurs qui font s'illuminer une seule protéine.",
  imatinib: "Le médicament qui a ouvert l'ère des thérapies ciblées en 2001, faisant de la leucémie myéloïde chronique une maladie gérable avec une espérance de vie proche de la normale.",
  "immune-desert-exclusion": "Les tumeurs présentent trois 'climats' immunitaires : enflammé (lymphocytes T à l'intérieur, les médicaments anti-points de contrôle fonctionnent), exclu (lymphocytes T bloqués en périphérie) et désert (aucun lymphocyte T). La plupart des cancers fréquents sont exclus ou déserts, et les rendre 'chauds' est le problème central de l'immunothérapie.",
  "immuno-pet": "Des examens PET réalisés avec des anticorps radiomarqués ou leurs fragments, pour visualiser toute protéine qu'un anticorps peut atteindre, y compris les cellules immunitaires à l'intérieur des tumeurs.",
  immunotherapy: "L'immunothérapie aide le système immunitaire du patient lui-même à reconnaître et à détruire le cancer.",
  "immunotherapy-roadmap": "La feuille de route de l'immunothérapie est un arc de 130 ans, de l'injection de bactéries dans les tumeurs à la levée des freins immunitaires, et aujourd'hui à la conception de la réponse immunitaire elle-même avec des vaccins, des anticorps engageurs et des cellules.",
  "imrt-igrt": "Une radiothérapie modelée avec précision sur la tumeur et contrôlée par une imagerie quotidienne, pour épargner les organes voisins.",
  imvigor011: "Le premier essai à utiliser un test sanguin de détection du cancer résiduel pour décider qui reçoit une immunothérapie, et cela a fonctionné.",
  "in-vivo-car-t": "Au lieu de modifier les lymphocytes T en usine, une injection les reprogramme directement dans le corps du patient.",
  "inflammation-nfkb": "L'inflammation chronique est un terreau pour le cancer : elle alimente les signaux de croissance, les dommages à l'ADN et la suppression immunitaire. L'interrupteur NF-κB à l'intérieur des cellules en est le relais principal, et la colite, l'hépatite et la gastrite à H. pylori en sont la preuve clinique.",
  "inflammatory-myofibroblastic-tumour": "L'IMT est une tumeur rare faite de cellules fusiformes mêlées à des cellules inflammatoires, le plus souvent dans le poumon ou l'abdomen d'enfants et de jeunes adultes. La chirurgie guérit la plupart des cas, et environ la moitié portent une fusion du gène ALK, de sorte que le comprimé bloquant ALK, le crizotinib, est approuvé pour les tumeurs qui ne peuvent pas être retirées, l'une des premières approbations de thérapie ciblée pour une tumeur solide de l'enfant.",
  "integrative-oncology": "Utiliser des approches complémentaires fondées sur des preuves réelles, comme l'acupuncture contre les nausées et la douleur, le yoga et la pleine conscience contre l'anxiété et la fatigue, en complément du traitement standard, tout en éloignant les patients des thérapies 'alternatives' non prouvées qui peuvent raccourcir la vie.",
  "intismeran-autogene": "Un vaccin mRNA sur mesure codant jusqu'à 34 mutations propres à la tumeur du patient. En août 2026, il est devenu le premier vaccin anticancéreux personnalisé à remporter un essai de phase 3.",
  "intravasation-ctc-survival": "Entrer dans la circulation sanguine et y survivre est brutal : les cellules sont arrachées à leurs voisines, malmenées par le flux et traquées par les cellules NK. Moins d'une sur mille survit. Celles qui y parviennent voyagent en grappes, se couvrent d'un manteau de plaquettes ou s'accrochent aux neutrophiles. Les biopsies liquides capturent ce qui reste.",
  "invasion-ecm-degradation": "Pour envahir, une cellule cancéreuse doit s'agripper à l'échafaudage qui l'entoure, se frayer un chemin avec des enzymes et se tirer vers l'avant, seule ou en file menée par une cellule éclaireuse. Les fibroblastes ouvrent souvent la voie en premier. Les bloqueurs d'enzymes des années 1990 ont échoué ; les cibles d'aujourd'hui sont l'accroche (intégrines, FAK) et les ouvreurs de voie.",
  ipilimumab: "Ipilimumab a été le premier inhibiteur de point de contrôle (2011) et a prouvé que le système immunitaire pouvait être libéré contre le cancer.",
  irae: "Les effets indésirables d'origine immunitaire (irAEs) sont les effets secondaires auto-immuns des inhibiteurs de points de contrôle : colite, troubles de la thyroïde, éruption cutanée, hépatite, pneumopathie inflammatoire.",
  irinotecan: "Irinotecan est une chimiothérapie bloquant la topoisomérase, au cœur des protocoles contre les cancers de l'intestin et du pancréas (FOLFIRI, FOLFIRINOX, NALIRIFOX) et du traitement de rattrapage des sarcomes de l'enfant ; il porte la même 'ogive' que les charges des ADC au deruxtecan.",
  ivonescimab: "Un anticorps bispécifique chinois qui a battu Keytruda en comparaison directe sur la survie sans progression dans le cancer du poumon, le premier médicament à y parvenir.",
  ivosidenib: "Ivosidenib est un comprimé qui bloque l'enzyme IDH1 mutée, approuvé dans le cancer des voies biliaires et dans la leucémie.",
  "izalontamab-brengitecan": "Izalontamab brengitecan est le premier ADC bispécifique à réussir un essai de phase 3, en frappant deux récepteurs de croissance à la fois dans le cancer du sein triple négatif.",
  "johns-hopkins": "Johns Hopkins est le berceau de la génomique du cancer (Vogelstein), de l'immunothérapie des tumeurs MSI-high (Le, Diaz) et de la science de la biopsie liquide et du MCED (CancerSEEK).",
  "johnson-johnson": "Johnson & Johnson est en tête dans le myélome multiple (Darzalex, Carvykti, Tecvayli, Talvey) et dans les anticorps bispécifiques contre le cancer du poumon (Rybrevant).",
  karolinska: "Le principal hôpital de cancérologie de Suède, lié au Karolinska Institutet et à l'Assemblée Nobel, avec une solide recherche fondée sur les registres.",
  "keynote-522": "L'essai qui a ajouté l'immunothérapie à la chimiothérapie préopératoire du cancer du sein triple négatif et qui, fait unique, a amélioré la survie.",
  kinase: "Une enzyme qui active d'autres protéines en leur accrochant un groupe phosphate. La signalisation du cancer fonctionne grâce aux kinases, et les inhibiteurs de kinases constituent la plus grande classe de médicaments ciblés.",
  "kinase-inhibitors": "Des comprimés qui bloquent l'enzyme précise dont un cancer dépend. Imatinib a prouvé en 2001 qu'un cancer pouvait être éteint de manière délibérée.",
  kit: "La mutation de KIT est le moteur de la plupart des tumeurs stromales gastro-intestinales, et la raison pour laquelle imatinib a transformé un sarcome dont la survie médiane était d'environ un an en une maladie chronique.",
  kras: "KRAS est le gène du cancer le plus fréquemment muté, qualifié de 'non ciblable' pendant 40 ans, jusqu'en 2021.",
  "kras-inhibitors": "Des médicaments contre le gène du cancer le plus fréquent, jugé impossible à cibler jusqu'à sotorasib en 2021.",
  lag3: "LAG-3 est le troisième frein immunitaire à obtenir une approbation, en association avec le blocage de PD-1 dans le mélanome.",
  "rare-childhood-cancers": "Certains cancers de l'enfant sont si rares qu'aucun hôpital n'en voit assez, à lui seul, pour en tirer des enseignements. Le NCI les regroupe : tumeurs du cœur, papillomes des voies respiratoires, cancers de la thyroïde, des surrénales, du nez et de la gorge, mélanome et carcinomes plus typiques de l'adulte. La réponse a été la création de registres internationaux et de réseaux d'experts qui rassemblent chaque cas, de sorte qu'il existe des recommandations de traitement même sans essais cliniques.",
  "ras-mapk": "La voie RAS-MAPK est le relais qui donne à la cellule l'ordre de se diviser. Un signal reçu à la surface active RAS, qui transmet le message à RAF, MEK puis ERK, lesquels indiquent au noyau de faire se diviser la cellule. Les mutations de KRAS et de BRAF la bloquent en position « allumée ».",
  "real-world-evidence": "Données issues des soins courants plutôt que des essais cliniques, utilisées pour vérifier si les résultats se confirment en dehors de la population des essais.",
  recist: "RECIST est le règlement qui sert à mesurer, sur les examens d'imagerie, si les tumeurs ont grossi ou diminué.",
  "replication-stress": "Les cancers copient leur ADN trop vite et avec des points de contrôle défaillants, si bien que les fourches de réplication se bloquent et s'effondrent. Ils ne survivent qu'en s'appuyant sur des kinases de réparation d'urgence comme ATR, CHK1 et WEE1, c'est pourquoi bloquer ces kinases peut être létal de façon sélective.",
  resistance: "Pourquoi les médicaments anticancéreux cessent d'agir : soit la tumeur n'a jamais dépendu de la cible, soit elle évolue pour contourner le blocage.",
  "resistance-routes-map": "Quand un médicament bloque le moteur d'un cancer, celui-ci dispose de cinq voies de retour : modifier la pièce à laquelle le médicament se fixe, en produire davantage, emprunter une route parallèle, passer à un tout autre moteur, ou cesser de laisser entrer le médicament. Savoir quelle voie la tumeur a empruntée détermine le médicament suivant.",
  ret: "RET est une kinase altérée dans le cancer de la thyroïde et dans une petite fraction des cancers du poumon, que l'on peut traiter avec un seul comprimé sélectif, quel que soit l'endroit où se trouve la tumeur.",
  revumenib: "Revumenib (Revuforj) est le premier inhibiteur de la ménine (2024), destiné aux leucémies aiguës présentant un réarrangement de KMT2A ou une mutation de NPM1.",
  ribociclib: "Ribociclib est l'inhibiteur de CDK4/6 dont le bénéfice sur la survie est le plus constant, approuvé depuis 2024 pour une large population de patients atteints d'un cancer du sein précoce.",
  rituximab: "Rituximab a été le premier anticorps jamais approuvé contre le cancer (1997). Il a fait de la chimio-immunothérapie le traitement standard de la CLL pendant une décennie, et les biosimilaires le maintiennent bon marché et disponible partout.",
  "rna-seq": "Mesurer quels gènes une tumeur utilise activement, ce qui révèle son sous-type et permet de trouver des fusions de gènes.",
  "robotic-surgery": "Les chirurgiens opèrent par de petites incisions à l'aide de bras robotisés, avec une précision sans tremblement et une vision en 3D.",
  "roche-genentech": "Créatrice d'Herceptin, d'Avastin et de Rituxan, et propriétaire de Foundation Medicine ; l'entreprise qui a défini l'oncologie par anticorps.",
  "royal-marsden": "The Royal Marsden a été le premier hôpital du monde consacré au cancer (1851) et travaille en tandem avec l'Institute of Cancer Research.",
  "rtk-activation": "Les récepteurs des facteurs de croissance sont des antennes à la surface de la cellule qui s'apparient quand un signal arrive et allument les relais de croissance à l'intérieur. Les cancers mutent, multiplient ou fusionnent ces antennes pour qu'elles diffusent l'ordre « croître » sans aucun signal. La plupart des médicaments ciblés, des anticorps et des ADC commencent ici.",
  "sacituzumab-govitecan": "Le premier ADC ciblant TROP2. Il délivre une chimiothérapie puissante directement aux cellules des cancers du sein et de la vessie, et constitue désormais une option de première ligne dans le cancer du sein triple négatif.",
  "sacituzumab-tirumotecan": "Sacituzumab tirumotecan est un troisième ADC anti-TROP2 venu de Chine, dont la licence a été cédée à Merck pour un très vaste programme mondial. Il est approuvé en Chine ; aux États-Unis, il bénéficie d'un bon d'examen prioritaire mais n'est pas encore approuvé.",
  sanofi: "Sanofi fabrique Sarclisa (isatuximab), désormais disponible sous une forme sous-cutanée approuvée en juillet 2026.",
  sbrt: "Des doses de radiothérapie très élevées et très précises, délivrées en 1 à 5 séances, capables de détruire une tumeur comme le ferait la chirurgie.",
  "scalp-cooling": "Un bonnet bien ajusté, refroidi à quelques degrés au-dessus de zéro et porté avant, pendant et après chaque perfusion de chimiothérapie, resserre les vaisseaux sanguins du cuir chevelu afin que moins de médicament atteigne les racines des cheveux. Dans un essai randomisé, environ la moitié des femmes sous chimiothérapie à base de taxanes ont gardé la plupart de leurs cheveux, contre aucune parmi celles qui n'en portaient pas.",
  screening: "Tester des personnes sans symptômes pour repérer un cancer, ou ses lésions précurseurs, assez tôt pour le guérir. Son efficacité est prouvée pour les cancers du sein, du col de l'utérus, colorectal et (chez les fumeurs) du poumon ; chaque test détecte aussi certains cancers qui n'auraient jamais causé de tort.",
  seer: "SEER enregistre combien de personnes aux États-Unis développent chaque cancer et combien de temps elles vivent, selon le stade, l'âge, l'origine ethnique et l'année.",
  selpercatinib: "Selpercatinib est un inhibiteur sélectif de RET approuvé pour toute tumeur porteuse d'une fusion RET, avec une nouvelle mise à jour de son indication en juillet 2026.",
  "sentinel-node": "Retirer seulement le premier ganglion lymphatique vers lequel la tumeur se draine, plutôt que tous, pour vérifier s'il y a propagation.",
  sgo: "La société américaine des oncologues gynécologues, dont l'Annual Meeting on Women's Cancer est le congrès où sont présentés les essais d'inhibiteurs de PARP et d'immunothérapie dans les cancers de l'ovaire, de l'endomètre et du col de l'utérus.",
  "shared-antigen-vaccine": "Des vaccins dirigés contre des mutations ou des protéines communes à de nombreux patients, ce qui permet de les fabriquer à l'avance.",
  sheba: "Le plus grand hôpital d'Israël, dont le centre de cancérologie a dirigé l'essai POLO sur l'olaparib dans le cancer du pancréas et qui gère l'un des rares programmes de thérapie par TIL au monde.",
  signatera: "Le test sanguin le plus utilisé pour détecter un reliquat de cancer après la chirurgie, personnalisé selon les mutations tumorales de chaque patient.",
  "single-cell-spatial": "Lire les gènes de chaque cellule individuellement et cartographier la position de chaque cellule dans la tumeur.",
  "targeted-therapy": "Les thérapies ciblées sont des médicaments conçus pour désactiver une protéine défectueuse précise dont le cancer dépend.",
  tarlatamab: "Le premier engageur de lymphocytes T à améliorer la survie dans une tumeur solide fréquente, le cancer du poumon à petites cellules.",
  "tata-memorial": "Le plus grand centre de cancérologie d'Inde, pionnier des essais à faible coût et à fort impact, comme l'immunothérapie à faible dose et la chimiothérapie métronomique orale.",
  "tcr-t": "Des lymphocytes T dotés par ingénierie d'un récepteur qui reconnaît des fragments de protéines situées à l'intérieur de la cellule cancéreuse, atteignant ainsi des cibles inaccessibles aux CAR-T.",
  tebentafusp: "Le premier médicament à améliorer la survie dans le mélanome uvéal métastatique, et le premier bispécifique fondé sur un TCR.",
  teclistamab: "Teclistamab a été le premier bispécifique prêt à l'emploi pour le myélome multiple, et il est désormais approuvé après une seule ligne de traitement antérieure.",
  temozolomide: "La seule chimiothérapie dont il est prouvé qu'elle prolonge la vie dans le glioblastome, administrée pendant et après la radiothérapie. Elle est plus efficace lorsque la tumeur a désactivé un gène de réparation appelé MGMT.",
  tempus: "Des tests génomiques associés à l'un des plus grands ensembles de données cliniques multimodales, utilisés pour des modèles d'IA et l'appariement aux essais cliniques.",
  "tenosynovial-giant-cell-tumour": "La TGCT est une tumeur bénigne mais destructrice de la membrane qui tapisse l'articulation, dans laquelle quelques cellules porteuses d'une fusion du gène CSF1 recrutent une foule de cellules immunitaires normales qui rongent l'articulation. La chirurgie guérit la plupart des formes localisées, et dans la maladie diffuse ou récidivante, deux comprimés qui bloquent le récepteur du CSF1, le pexidartinib et le vimseltinib, font régresser les tumeurs et rétablissent la fonction de l'articulation.",
  theranostics: "Utiliser la même molécule de ciblage pour un examen d'imagerie diagnostique et pour un traitement, afin de traiter exactement ce que l'on voit.",
  "therascreen-cdx": "Une famille de tests rapides portant sur un seul gène, qui déterminent qui peut recevoir plusieurs médicaments contre les cancers de l'intestin, du poumon, du sein et de la vessie.",
  "thermal-ablation": "L'ablation thermique détruit une tumeur par la chaleur ou le froid délivrés à travers une aiguille, sans aucune incision.",
  "thomas-powles": "A dirigé EV-302, NIAGARA et IMvigor011, les essais qui ont fait passer le cancer de la vessie d'une prise en charge fondée uniquement sur la chimiothérapie à des soins par ADC, immunothérapie et guidés par le ctDNA.",
  "til-therapy": "Des cellules immunitaires qui ont déjà pénétré dans la tumeur sont prélevées, multipliées jusqu'à plusieurs milliards, puis réinjectées.",
  tils: "Des cellules immunitaires qui ont pénétré à l'intérieur de la tumeur. Plus elles sont nombreuses, meilleurs sont les résultats dans le cancer du sein triple négatif.",
  tisagenlecleucel: "Tisagenlecleucel a été la toute première thérapie CAR-T approuvée (2017), pour les enfants et les jeunes adultes dont la leucémie était revenue après tous les autres traitements.",
  tislelizumab: "Un bloqueur de PD-1 développé en Chine, conçu pour éviter une voie parallèle qui peut atténuer l'effet d'autres médicaments anti-PD-1, désormais approuvé aux États-Unis et dans l'UE pour le cancer de l'œsophage et de l'estomac.",
  tmb: "Le nombre de mutations que porte une tumeur. Plus il y a de mutations, plus le système immunitaire a de cibles.",
  "tnbc-history": "Comment le cancer du sein triple négatif est passé, en six ans, du sous-type sans aucune thérapie ciblée à un sous-type disposant d'une immunothérapie, d'inhibiteurs de PARP, de trois ADC et d'un ADC bispécifique aux résultats positifs.",
  "topoisomerase-inhibitors": "Les inhibiteurs de la topoisomérase I agissent en bloquant l'enzyme qui démêle l'ADN pendant sa copie. Ils sont peu efficaces sous forme libre dans de nombreux cancers, mais redoutables lorsqu'ils sont délivrés par un ADC.",
  tp53: "TP53 est le « gardien du génome », défectueux dans la moitié de tous les cancers. Le réparer directement a jusqu'ici fait échouer toutes les tentatives, alors les médicaments exploitent ce dont sa perte rend les cancers dépendants.",
  "transcription-addiction": "Les cellules cancéreuses font tourner quelques gènes (MYC, leurs facteurs de lignée, leurs oncogènes de fusion) à un volume extrême à partir de régions de contrôle géantes appelées super-enhancers. Les amplificateurs, BRD4, CDK7, CDK9 et Mediator, sont les mêmes dans toutes les cellules, mais les cancers en dépendent de façon inhabituelle, et cette dépendance peut être ciblée par des médicaments.",
  trastuzumab: "Le premier anticorps ciblé pour une tumeur solide (1998), qui a fait passer le cancer du sein HER2 positif du pire sous-type à l'un des plus faciles à traiter.",
  "trastuzumab-deruxtecan": "Trastuzumab deruxtecan (Enhertu) est l'ADC le plus réussi de tous les temps. Il a redéfini HER2 en agissant sur des tumeurs ne portant que d'infimes quantités de la protéine, et en 2026 il a fait son entrée dans le cancer du sein à un stade précoce.",
  "trastuzumab-emtansine": "Trastuzumab emtansine (Kadcyla, T-DM1) a été le premier ADC pour une tumeur solide (2013). Il reste le traitement standard après la chirurgie chez les patientes atteintes d'un cancer du sein HER2+ dont la tumeur n'a pas complètement répondu au traitement préopératoire.",
  trop2: "Une protéine présente à la surface de nombreuses cellules cancéreuses en bien plus grande quantité que sur les cellules normales, ce qui en fait une bonne adresse pour y acheminer des médicaments.",
  "trop2-adc-roadmap": "Une cible, trois médicaments approuvés ou presque, et une quatrième vague. Comment TROP2 est passé d'un obscur antigène du trophoblaste au cœur du traitement des cancers du sein et du poumon.",
  "trop2-pet": "Un examen PET expérimental qui montre si une tumeur porte la protéine TROP2, afin que les médecins puissent choisir le bon ADC avant de l'administrer.",
  tucatinib: "Un comprimé sélectif de HER2 qui agit dans le cerveau, pour le cancer du sein HER2 positif avec métastases cérébrales.",
  "tumor-dormancy": "Les cellules cancéreuses peuvent se cacher dans la moelle osseuse, le poumon ou le cerveau pendant des années ou des décennies, endormies et invisibles aux examens d'imagerie comme à la chimiothérapie, puis se réveiller. La rechute tardive dans le cancer du sein et de la prostate correspond à la fin de cette dormance.",
  "dabrafenib-trametinib": "Dabrafenib plus trametinib est l'association en comprimés BRAF plus MEK, approuvée pour le cancer du poumon BRAF V600E et, depuis 2022, pour toute tumeur solide porteuse de cette mutation.",
  dactinomycin: "Le premier antibiotique utilisé comme médicament anticancéreux (1954), toujours au cœur de la chimiothérapie de la tumeur de Wilms, du rhabdomyosarcome et de la maladie trophoblastique gestationnelle.",
  "daiichi-sankyo": "Daiichi Sankyo est l'entreprise japonaise dont la technologie de charge utile DXd a créé la meilleure plateforme d'ADC du secteur.",
  "dana-farber": "Là où la chimiothérapie est née (Farber, 1948) et où une grande partie de l'oncologie moderne du sein, du poumon et du myélome a été définie.",
  daratumumab: "L'anticorps anti-CD38 qui a transformé les triplets en quadruplets : l'ajouter à l'induction standard divise à peu près par deux le risque de progression du myélome.",
  daraxonrasib: "Le premier médicament qui bloque toutes les formes actives de RAS, approuvé par la FDA en août 2026 pour le cancer du pancréas métastatique, où KRAS est le moteur de 90 % des tumeurs.",
  "datopotamab-deruxtecan": "Datopotamab deruxtecan (Datroway) est le deuxième ADC ciblant TROP2 et partage la charge utile d'Enhertu. En 2026, il est devenu une option de première ligne pour les patientes atteintes d'un cancer du sein triple négatif qui ne peuvent pas recevoir d'immunothérapie.",
  ddr: "La réponse aux dommages de l'ADN est l'ensemble des équipes de réparation de la cellule. Les cassures simple brin sont réparées par PARP ; les cassures double brin par la recombinaison homologue, qui dépend de BRCA. Si une équipe manque, la cellule survit ; si les deux manquent, elle meurt. C'est ainsi que fonctionnent les inhibiteurs de PARP.",
  "desmoid-tumour": "Les tumeurs desmoïdes sont des proliférations localement agressives de cellules semblables aux fibroblastes qui ne se propagent jamais à des organes distants mais peuvent envahir les nerfs, l'intestin et les muscles. Beaucoup cessent de grossir ou régressent d'elles-mêmes, si bien que la surveillance initiale est désormais la norme, et pour celles qui progressent, le premier médicament conçu pour cette maladie, l'inhibiteur de la gamma-sécrétase nirogacestat, réduit les tumeurs et soulage la douleur.",
  devices: "Les dispositifs et les thérapies physiques traitent le cancer avec des champs électriques, de la chaleur ou des sons plutôt qu'avec des produits chimiques.",
  diagnostics: "Des tests sur les tissus et le sang qui indiquent de quel type de cancer il s'agit, ce qui le fait progresser et quels médicaments pourraient être efficaces.",
  "dietary-fibre-microbiome-io": "Les patients qui consomment beaucoup de fibres et évitent les comprimés de probiotiques semblent mieux répondre à l'immunothérapie du mélanome, probablement parce que les fibres nourrissent les bonnes bactéries intestinales. Un véritable essai clinique est en cours.",
  "dietary-supplements-treatment-interactions": "La plupart des personnes traitées pour un cancer prennent des compléments, souvent sans en informer leur équipe soignante. Les antioxydants, le millepertuis, les vitamines à forte dose et certaines plantes peuvent atténuer l'effet de la chimiothérapie ou de la radiothérapie, ou interagir avec les thérapies ciblées.",
  "dietitian-led-weight-loss-breast": "Le surpoids après un cancer du sein est associé à davantage de récidives ; un essai portant sur 3 000 femmes a donc testé un programme téléphonique de perte de poids de deux ans. Les femmes ont perdu du poids, mais l'essai n'a pas clairement montré moins de récidives.",
  "digital-pathology-ai": "Numériser les lames de microscope et laisser un logiciel mesurer ce qu'un pathologiste ne peut pas voir, y compris prédire qui bénéficiera d'un traitement.",
  "dipg-dmg": "Le gliome diffus de la ligne médiane se développe à travers le tronc cérébral et ne peut pas être retiré chirurgicalement. Un seul changement dans une protéine histone (H3 K27M) modifie la façon dont la tumeur lit son ADN. La radiothérapie a longtemps été la seule aide ; en 2025, le premier médicament visant cette tumeur, dordaviprone (ONC201), a été approuvé après une réduction durable chez certains patients, et les cellules CAR-T anti-GD2 ont produit des réponses précoces remarquables.",
  dkfz: "Le DKFZ est le plus grand institut de recherche sur le cancer d'Allemagne ; c'est là que Harald zur Hausen a établi le lien entre le HPV et le cancer du col de l'utérus (Nobel 2008).",
  dll3: "Une protéine présente à la surface des cellules du cancer du poumon à petites cellules, désormais ciblée par un médicament qui attire les lymphocytes T vers elles.",
  "dna-replication-licensing": "Avant de se diviser, une cellule doit copier trois milliards de lettres d'ADN exactement une fois. Pour cela, elle « autorise » à l'avance des milliers de points de départ, puis les déclenche par vagues. Les cancers en déclenchent trop et trop vite, et de nombreuses chimiothérapies agissent en affamant ou en bloquant la machinerie de copie.",
  docetaxel: "La première chimiothérapie à prolonger la vie dans le cancer de la prostate (2004), aujourd'hui intégrée au traitement triple dès le diagnostic initial de la maladie métastatique.",
  dosimetry: "Mesurer la dose de rayonnement que chaque organe et chaque tumeur ont réellement reçue d'un médicament radioactif.",
  dostarlimab: "Dostarlimab est un bloqueur de PD-1 célèbre pour avoir fait disparaître le cancer du rectum sans chirurgie chez tous les patients dont la tumeur présentait un déficit de réparation des mésappariements.",
  doxorubicin: "Le médicament de chimiothérapie rouge issu d'une bactérie du sol qui reste le pilier du traitement du sarcome, du lymphome et du cancer du sein, limité par les dommages cardiaques cumulatifs.",
  "drug-discovery": "Les plateformes de découverte de médicaments sont les outils utilisés pour trouver le prochain médicament : criblages génétiques, organoïdes, modèles chez la souris et IA.",
  "drug-efflux-pumps": "Les cellules cancéreuses peuvent installer dans leur membrane externe des pompes qui rejettent la chimiothérapie aussi vite qu'elle entre. Ces mêmes pompes protègent l'intestin, le cerveau et la moelle osseuse dans les tissus sains, ce qui explique pourquoi les bloquer a échoué comme stratégie et pourquoi les concepteurs de médicaments choisissent désormais des charges utiles que les pompes ne peuvent pas saisir.",
  "drug-tolerant-persisters": "Même lorsqu'un médicament élimine 99 % d'une tumeur, quelques cellules survivent sans aucune mutation de résistance : elles se mettent en veille, cessent de se diviser et attendent. Ces cellules persistantes sont le germe de la rechute. Elles sont difficiles à tuer précisément parce qu'elles ne font pas grand-chose, mais elles ont leurs propres faiblesses.",
  "ductal-carcinoma-in-situ": "Le DCIS correspond à des cellules anormales confinées aux canaux galactophores ; ce n'est pas encore un cancer invasif et il ne peut pas se propager, mais une partie deviendrait invasive si on la laissait évoluer. Le traitement, généralement une tumorectomie avec radiothérapie ou une mastectomie, est très efficace, si bien que la vraie question est de savoir quels DCIS à faible risque peuvent être surveillés en toute sécurité. Le premier essai randomisé de surveillance active (2024) a montré qu'elle n'était pas moins bonne à deux ans.",
  durvalumab: "Un bloqueur de PD-L1 devenu le standard après chimioradiothérapie dans le cancer du poumon de stade III, et désormais utilisé aussi dans les cancers de la vessie, des voies biliaires et de l'estomac.",
  dynamic: "A montré qu'un test sanguin peut réduire de moitié, en toute sécurité, le nombre de patients atteints d'un cancer du côlon recevant une chimiothérapie après la chirurgie.",
  "early-detection": "La détection précoce et le dépistage consistent à trouver le cancer avant qu'il ne provoque des symptômes, au moment où il est le plus curable.",
  lancet: "The Lancet est la principale revue médicale généraliste britannique et l'autre grand lieu de publication des essais en cancérologie qui changent la pratique, avec une voix plus forte que le NEJM sur la santé mondiale et les politiques de santé.",
  "langerhans-cell-histiocytosis": "L'histiocytose à cellules de Langerhans est une maladie dans laquelle un petit groupe de cellules immunitaires porteuses d'un signal de croissance défectueux (le plus souvent une mutation de BRAF) s'accumule dans les os, la peau, l'hypophyse ou les organes. Elle va d'une lésion osseuse unique qui guérit après la biopsie à une maladie menaçant la vie chez le nourrisson. Une année de chimiothérapie douce guérit la plupart des enfants, et les inhibiteurs de BRAF ou de MEK sauvent ceux dont la maladie résiste.",
  larotrectinib: "Le premier médicament approuvé pour une fusion de gènes quel que soit l'organe d'origine du cancer ; il agit dans environ 75 % des cancers avec fusion NTRK, du fibrosarcome du nourrisson aux cancers des glandes salivaires et de la thyroïde.",
  "late-effects": "Problèmes de santé qui apparaissent des mois ou des décennies après la fin du traitement : atteinte cardiaque, infertilité, seconds cancers, lymphœdème, sécheresse buccale, troubles de la mémoire, fragilité osseuse. Ils comptent surtout pour les enfants et les jeunes adultes, qui vivent le plus longtemps avec eux.",
  lenalidomide: "Un descendant du thalidomide qui active le système d'élimination des protéines de la cellule contre deux facteurs de survie du myélome, et qui constitue le pilier du traitement d'entretien du myélome et de nombreux protocoles contre les lymphomes.",
  lenvatinib: "Un comprimé oral anti-angiogénique qui a égalé le sorafenib dans le cancer du foie avec des taux de réponse plus élevés, et qui s'associe au pembrolizumab dans le cancer du rein et de l'endomètre.",
  letrozole: "Des comprimés quotidiens qui empêchent le corps de fabriquer des œstrogènes après la ménopause, pilier de l'hormonothérapie pour la plupart des cancers du sein.",
  lifileucel: "Lifileucel a été la première thérapie TIL approuvée : les propres cellules immunitaires du patient qui combattent la tumeur sont multipliées jusqu'à atteindre des milliards, puis lui sont réinjectées.",
  "limb-salvage-surgery": "Retirer un sarcome de l'os ou des tissus mous en conservant le bras ou la jambe, puis reconstruire avec des implants métalliques, des greffes osseuses ou, chez l'enfant, des prothèses de croissance.",
  "lineage-plasticity-neuroendocrine": "Sous la pression d'un médicament qui bloque son identité (le récepteur des androgènes dans le cancer de la prostate, l'EGFR dans le cancer du poumon), une tumeur peut changer de type cellulaire et devenir un cancer neuroendocrine à petites cellules qui n'a plus besoin du signal bloqué. C'est l'échappement ultime : non pas une nouvelle mutation dans le moteur, mais un nouveau moteur.",
  "lipid-metabolism-cancer": "Les cellules qui se divisent ont besoin de membranes, et les membranes sont faites de graisse. Les cancers activent les enzymes de fabrication des graisses que la plupart des tissus adultes gardent éteintes, et dans les environnements gras (sein, épiploon, moelle osseuse) ils volent aussi des lipides aux cellules graisseuses voisines. Cela relie l'obésité au cancer et offre de nouvelles cibles thérapeutiques.",
  "liquid-biopsy": "Un test sanguin qui lit les fragments d'ADN libérés par la tumeur, ce qui permet de génotyper ou de surveiller le cancer sans piquer la tumeur avec une aiguille.",
  "liver-transplant-oncology": "Remplacer la totalité du foie malade guérit à la fois le cancer et la cirrhose sous-jacente, chez les patients dont les tumeurs sont suffisamment petites.",
  lorlatinib: "Un inhibiteur d'ALK offrant le contrôle de la maladie le plus long jamais enregistré pour un comprimé ciblé contre le cancer du poumon : 60 % sans progression à cinq ans.",
  "low-dose-ct-screening": "Un scanner annuel à faible dose de rayonnement, destiné aux gros fumeurs actuels et anciens, qui détecte le cancer du poumon assez tôt pour le guérir.",
  lutathera: "Lutetium-177 dotatate a été la première thérapie moderne par radioligand (2018), pour les tumeurs neuroendocrines, et est désormais utilisé en première ligne.",
  "male-breast-cancer": "Les hommes aussi ont des cancers du sein, généralement d'un type hormonosensible découvert sous la forme d'une boule près du mamelon. Le traitement ressemble beaucoup à celui des femmes, avec chirurgie, radiothérapie et tamoxifen, et les mutations héréditaires de BRCA2 sont assez fréquentes pour qu'un test génétique soit proposé à tout homme diagnostiqué. La principale amélioration en cours consiste à inclure les hommes dans les essais cliniques, afin que leur prise en charge cesse d'être empruntée à celle des femmes.",
  mammography: "Radiographie du sein à faible dose utilisée pour le dépistage. Les versions 3D plus récentes détectent davantage de cancers avec moins de fausses alertes.",
  "mayo-clinic": "Régulièrement classé premier hôpital des États-Unis toutes spécialités confondues, avec une solide activité de protonthérapie et le premier centre d'ions carbone des États-Unis en construction.",
  mced: "Un test sanguin unique conçu pour dépister des dizaines de cancers à la fois, y compris ceux pour lesquels il n'existe aucun dépistage aujourd'hui.",
  "md-anderson": "MD Anderson est le plus grand centre de cancérologie du monde en volume de patients, avec le plus important programme de phase 1 et un effort de premier plan sur les CAR-NK.",
  "mediterranean-plant-forward-diet": "Les régimes fondés sur les légumes, les céréales complètes, les légumineuses, les noix, le poisson et l'huile d'olive, avec peu de viande rouge ou transformée, sont associés à un risque de cancer plus faible et à une meilleure survie après le diagnostic. Les preuves sont solides pour le régime dans son ensemble, faibles pour un aliment pris isolément.",
  menin: "Une protéine d'échafaudage dont certaines leucémies ont besoin pour maintenir leurs gènes activés ; le premier médicament dirigé contre elle a été approuvé en 2024.",
  merck: "Merck & Co. (MSD) fabrique Keytruda, le médicament anticancéreux le plus vendu au monde, et prépare aujourd'hui son prochain acte autour des ADC ciblant TROP2 et des vaccins personnalisés.",
  met: "Un récepteur qui est soit muté dans certains cancers du poumon, soit amplifié comme voie d'échappement lorsque d'autres médicaments contre le cancer du poumon cessent d'agir.",
  "metastatic-cascade": "Comment le cancer se propage : les cellules quittent la tumeur, se glissent dans les vaisseaux sanguins ou lymphatiques, survivent au voyage, sortent dans un nouvel organe, y restent souvent endormies pendant des années, puis finissent par se développer. Les métastases causent environ 90 % des décès par cancer.",
  methotrexate: "L'antifolate de 1948 qui a produit les premières rémissions par chimiothérapie dans la leucémie de l'enfant et la première guérison d'une tumeur solide ; il reste essentiel dans l'ALL, le lymphome, l'ostéosarcome et le lymphome du système nerveux central.",
  "methylation-profiling": "Lecture des marques chimiques portées par l'ADN qui révèlent l'identité d'une cellule, utilisée pour classer les tumeurs cérébrales et pour détecter le cancer dans le sang.",
  mgh: "Le plus grand hôpital de Harvard ; des leaders de la thérapie ciblée du cancer du poumon, de la protonthérapie et de la recherche sur le ctDNA.",
  "mismatch-repair-msi": "Une fois l'ADN copié, une équipe de relecture corrige les lettres que la polymérase a mal recopiées. Si elle disparaît, le génome se remplit de milliers de petites erreurs, surtout dans les séquences répétitives (microsatellites). Ces erreurs produisent des protéines anormales que le système immunitaire peut voir, ce qui explique pourquoi l'immunothérapie fonctionne si bien dans ces cancers.",
  "paediatric-low-grade-glioma": "Les gliomes de bas grade de l'enfant sont des tumeurs cérébrales à croissance lente, presque toujours entraînées par un seul signal hyperactif, la voie MAPK, le plus souvent à cause d'une modification du gène BRAF. Comme l'interrupteur est connu, les comprimés qui le bloquent (dabrafenib avec trametinib, et tovorafenib) font aujourd'hui régresser les tumeurs bien plus souvent que la chimiothérapie, et de plus en plus d'enfants échappent à une irradiation du cerveau en développement.",
  palbociclib: "Palbociclib a été le premier inhibiteur de CDK4/6 (2015) et, en 2026, il est devenu le premier approuvé comme traitement d'entretien dans le cancer du sein HER2-positif et hormono-positif.",
  "palliative-care": "Des soins spécialisés pour les symptômes, la prise de décision et la qualité de vie, proposés en parallèle du traitement du cancer dès le diagnostic, et pas seulement en fin de vie. Les essais montrent qu'ils améliorent la qualité de vie et l'humeur et pourraient prolonger la survie.",
  "paper-ascent-nejm-2021": "Dans le cancer du sein triple négatif ayant déjà reçu au moins deux traitements, le conjugué anticorps-médicament ciblant TROP2 sacituzumab govitecan a à peu près doublé la durée de vie des patientes par rapport à la chimiothérapie standard.",
  "paper-breakwater-nejm-2025": "L'ajout d'un inhibiteur de BRAF et d'un anticorps anti-EGFR à la chimiothérapie de première ligne a à peu près doublé la survie dans le cancer de l'intestin métastatique porteur de la mutation BRAF V600E, l'un des sous-types de plus mauvais pronostic.",
  "paper-destiny-breast03-nejm-2022": "Un conjugué anticorps-médicament plus récent, le trastuzumab deruxtecan, a maintenu le cancer du sein métastatique HER2-positif sous contrôle environ quatre fois plus longtemps que l'ancien standard, le T-DM1, et a ensuite prolongé la survie.",
  "paper-destiny-breast04-nejm-2022": "Les cancers du sein n'ayant qu'un peu de HER2 à leur surface, longtemps qualifiés de HER2-négatifs, ont répondu au trastuzumab deruxtecan et les patientes ont vécu environ six mois de plus qu'avec la chimiothérapie. Cela a créé la catégorie HER2-faible.",
  "paper-ev-302-nejm-2024": "L'association du conjugué anticorps-médicament ciblant Nectin-4 enfortumab vedotin au pembrolizumab a presque doublé la survie par rapport à la chimiothérapie à base de platine dans le cancer urothélial avancé, la plus grande avancée dans cette maladie depuis 40 ans.",
  "paper-flaura-nejm-2018": "Commencer par l'osimertinib, un médicament anti-EGFR de troisième génération, plutôt que de le garder pour plus tard, a maintenu le cancer du poumon avec mutation de l'EGFR sous contrôle presque deux fois plus longtemps et a ensuite aidé les patients à vivre plus longtemps.",
  "paper-keynote-522-nejm-2022": "L'ajout de l'immunothérapie pembrolizumab à la chimiothérapie avant la chirurgie, puis sa poursuite après, a réduit d'environ un tiers le risque de rechute ou de décès dans le cancer du sein triple négatif de stade II-III et a ensuite amélioré la survie.",
  "paper-mariposa-nejm-2024": "L'association d'un anticorps bispécifique EGFR-MET à un comprimé anti-EGFR de troisième génération a fait mieux que l'osimertinib seul, retardant la progression d'environ sept mois et améliorant ensuite la survie, au prix de davantage d'effets secondaires.",
  "paper-olympia-nejm-2021": "Chez les femmes nées avec une mutation de BRCA1 ou BRCA2 dont le cancer du sein précoce était à haut risque, un an d'olaparib, un inhibiteur de PARP, après le traitement standard a réduit les rechutes de plus de 40% et a ensuite amélioré la survie.",
  parp: "PARP est une enzyme de réparation de l'ADN. Les cancers qui ont déjà perdu un système de réparation (BRCA) meurent quand ce second système est bloqué ; les cellules saines survivent.",
  "parp-inhibitor": "Des comprimés qui bloquent un système de secours de réparation de l'ADN, tuant les cellules cancéreuses qui ont déjà perdu leur système de réparation principal (BRCA).",
  "pathology-foundation-model": "De très grands modèles d'IA entraînés sur des millions de lames ou d'images médicales, qui peuvent être adaptés à presque n'importe quelle question diagnostique.",
  payload: "La charge utile est le poison transporté par un ADC, généralement une chimiothérapie bien trop toxique pour être administrée seule.",
  pcr: "Aucun cancer invasif restant dans le sein et les ganglions lymphatiques lorsque le chirurgien retire les tissus après le traitement préopératoire.",
  pd1: "PD-1 est un frein sur les cellules T. Le bloquer libère le système immunitaire contre la tumeur et a permis de guérir certains cancers auparavant incurables.",
  "pd1-checkpoint": "Comment les cellules T décident d'attaquer. Une cellule T doit voir sa cible (TCR-MHC) et recevoir un signal « feu vert » (CD28). PD-1 et CTLA-4 sont des signaux « stop » ; les tumeurs les exploitent. Les inhibiteurs de points de contrôle suppriment ce stop.",
  pdl1: "PD-L1 est le versant tumoral du frein PD-1, et aussi le biomarqueur qui décide qui reçoit une immunothérapie.",
  "pdx-models": "Une xénogreffe dérivée de patient est la tumeur d'un patient cultivée chez une souris, utilisée pour tester des médicaments avant qu'ils n'arrivent chez l'humain.",
  "pediatric-match": "Pediatric MATCH a été le premier essai national de médecine de précision pour les enfants : tout enfant avec une tumeur solide en rechute pouvait faire séquencer sa tumeur et, si un médicament correspondant existait, rejoindre le bras d'essai prévu pour lui. Il a prouvé que le mécanisme fonctionne, même si la plupart des médicaments donnés seuls ont eu peu d'effet.",
  pembrolizumab: "L'immunothérapie anticancéreuse la plus utilisée, approuvée dans plus de 40 indications, y compris avant et après la chirurgie du cancer du sein triple négatif.",
  penile: "Le cancer du pénis est un cancer de type cutané (épidermoïde), dont environ la moitié des cas sont dus au HPV, le même virus responsable du cancer du col de l'utérus. Il est très souvent guérissable quand il est détecté tôt, la chirurgie est devenue beaucoup moins mutilante, et la maladie peut être prévenue par la vaccination contre le HPV et l'hygiène. Les cas difficiles sont ceux avec atteinte des ganglions lymphatiques, pour lesquels la chimiothérapie associée à la chirurgie et, désormais, l'immunothérapie sont à l'essai.",
  "penn-abramson": "Là où la CAR-T est devenue un médicament (June, Levine ; Emily Whitehead), où le mRNA a été rendu utilisable comme médicament (Karikó, Weissman) et où la PET PARP a été inventée.",
  pertuzumab: "Un second anticorps anti-HER2 qui se fixe à un endroit différent du trastuzumab, empêchant HER2 de s'associer à HER3 ; ensemble, ils ont prolongé la survie de 16 mois dans CLEOPATRA.",
  pet: "Un examen d'imagerie qui montre où s'accumule un traceur radioactif, et qui visualise donc ce que font les tumeurs plutôt que leur apparence.",
  "pet-ct": "La PET et le CT dans une seule machine, de sorte que les zones actives sur la PET sont localisées avec précision sur le CT.",
  "peter-mac": "Peter Mac est le seul hôpital d'Australie entièrement dédié au cancer et un leader en théranostique, en CAR-T et en radiothérapie oncologique.",
  pfizer: "A acheté Seagen pour 43 milliards de dollars afin de devenir un leader des ADC ; fabrique aussi Ibrance, Lorbrena, Braftovi et le premier PROTAC.",
  pfs: "La survie sans progression (PFS) est la durée pendant laquelle les patients vivent sans que leur cancer ne progresse.",
  "pheochromocytoma-paraganglioma": "Les phéochromocytomes et les paragangliomes sont des tumeurs du tissu producteur d'adrénaline qui provoquent des poussées dangereuses de tension artérielle. La chirurgie, après un blocage soigneux de la tension artérielle, guérit la plupart des patients ; les tests génétiques trouvent une cause héréditaire dans près de la moitié des cas, et pour la minorité qui se propage, il existe désormais des médicaments radioactifs qui se fixent sur la tumeur et, depuis 2025, le premier comprimé ciblé par voie orale, le belzutifan.",
  "pi3k-akt-mtor": "Le circuit « croître et survivre » de la cellule. Les signaux de croissance venus de la surface activent PI3K, qui active AKT, qui active mTOR, lequel fabrique des protéines et bloque l'autodestruction.",
  pik3ca: "PIK3CA est le gène le plus souvent muté dans le cancer du sein hormonodépendant. Les médicaments qui le ciblent fonctionnent, mais il a fallu des années pour l'atteindre proprement sans faire monter la glycémie.",
  pirtobrutinib: "Un bloqueur de BTK qui fonctionne après que les plus anciens ont cessé d'agir, parce qu'il s'accroche à une autre partie de l'enzyme. Pleinement approuvé pour la CLL en décembre 2025.",
  "pituitary-tumours": "Les tumeurs hypophysaires sont généralement des excroissances bénignes de la glande hormonale située à la base du cerveau, qui posent problème en produisant trop d'hormones ou en comprimant les nerfs optiques. Les tumeurs productrices de prolactine fondent avec un comprimé, la plupart des autres sont guéries par une chirurgie passant par le nez, et les rares formes agressives répondent au médicament de chimiothérapie temozolomide.",
  "pku-cancer-hospital": "L'hôpital de Pékin dédié au cancer et le premier centre chinois pour les essais sur le cancer gastrique, où les CAR-T contre claudin 18.2 et les associations avec PD-1 ont été testées pour la première fois dans la maladie gastrique.",
  platinum: "Les agents à base de platine, comme le cisplatin et le carboplatin, agissent en créant des pontages dans l'ADN. Ils sont curatifs dans le cancer du testicule et occupent une place centrale dans le traitement des cancers du poumon, de l'ovaire, de la vessie, de la tête et du cou, et du TNBC.",
  "pleuropulmonary-blastoma": "Les tumeurs pulmonaires primitives de l'enfant sont rares et différentes du cancer du poumon de l'adulte. La plus importante, le blastome pleuropulmonaire, commence par un kyste pulmonaire chez le nourrisson et est due à un gène DICER1 défectueux, qui prédispose aussi aux tumeurs de la thyroïde, de l'ovaire et du rein. Repérer et retirer les kystes tôt, avec l'aide d'un registre international et de tests génétiques familiaux, empêche l'évolution vers les formes solides agressives.",
  pluvicto: "Un médicament radioactif qui va chercher PSMA sur les cellules du cancer de la prostate ; le radiopharmaceutique le plus vendu de tous les temps.",
  "post-transplant-lymphoproliferative-disorder": "Après une greffe d'organe ou de cellules souches, les médicaments qui empêchent le rejet empêchent aussi le système immunitaire de surveiller le virus d'Epstein-Barr, et les cellules B infectées peuvent se transformer en lymphome. La première mesure consiste à alléger l'immunosuppression ; viennent ensuite l'anticorps rituximab, une chimiothérapie si nécessaire et, plus récent encore, des lymphocytes T spécifiques du virus prêts à l'emploi qui rétablissent le contrôle immunitaire manquant.",
  ppv: "La valeur prédictive positive (PPV) est la probabilité qu'un test qui dit « cancer » ait raison.",
  "pre-metastatic-niche": "Avant même l'arrivée d'une seule cellule cancéreuse, la tumeur primitive envoie des colis en avance : de minuscules vésicules (exosomes) et des hormones qui recrutent des cellules de la moelle osseuse vers un organe distant et le transforment en terreau fertile. Quand la graine se pose, le lit est déjà fait.",
  prevention: "Empêcher le cancer d'apparaître : vaccins, tests génétiques germinaux, mode de vie, et médicaments ou chirurgie préventifs.",
  "princess-margaret": "Princess Margaret est le premier centre de cancérologie du Canada et un pionnier de l'immunothérapie et de la recherche sur les cellules souches cancéreuses.",
  "protac-degrader": "Au lieu de bloquer une protéine, ces médicaments l'étiquettent pour le système d'élimination des déchets de la cellule, qui la fait disparaître entièrement.",
  proteomics: "Mesurer les protéines d'une tumeur, qui sont ce que les médicaments atteignent réellement, plutôt que les gènes qui les codent.",
  "proton-therapy": "Une radiothérapie utilisant des protons, qui s'arrêtent dans la tumeur au lieu de la traverser, si bien que les tissus situés derrière ne reçoivent aucune dose.",
  prrt: "Une version radioactive de l'imitateur d'hormone utilisé pour l'examen d'imagerie ; elle se fixe sur les cellules de tumeur neuroendocrine et les irradie de l'intérieur.",
  psma: "Une protéine présente sur les cellules du cancer de la prostate qui permet aux médecins à la fois de voir le cancer sur un PET scan et de le frapper avec un médicament radioactif.",
  "psma-pet": "Un PET scan spécifique du cancer de la prostate qui détecte la propagation bien plus tôt que le CT ou la scintigraphie osseuse, et qui indique si un médicament radioactif correspondant sera efficace.",
  "race-for-children-act": "Une loi américaine qui oblige les laboratoires pharmaceutiques à tester les nouveaux médicaments anticancéreux ciblés chez les enfants dès que la cible du médicament joue un rôle dans un cancer de l'enfant, au lieu de les laisser ignorer les enfants parce que leurs cancers sont rares.",
  radiation: "Utiliser des faisceaux focalisés ou des particules radioactives pour tuer les cellules tumorales tout en épargnant les tissus sains.",
  "radioembolisation-tare": "Des millions de minuscules billes radioactives de verre ou de résine sont injectées dans l'artère du foie ; elles se logent dans la tumeur et l'irradient de l'intérieur.",
  radioimmunotherapy: "Fixer un atome radioactif à un anticorps, de sorte que le ciblage d'un ADC serve à délivrer une irradiation plutôt qu'une chimiothérapie.",
  "radioligand-therapy": "Un médicament qui trouve les cellules tumorales et transporte un atome radioactif qui les irradie depuis l'intérieur du corps.",
  "radiology-ai-screening": "Un logiciel qui lit les examens d'imagerie aux côtés des radiologues, détectant les cancers plus tôt et prédisant qui est à risque.",
  radiopharma: "Une molécule qui se fixe sur la tumeur transporte un atome radioactif. La même molécule avec un atome différent permet d'abord de voir la tumeur.",
  "radiopharma-roadmap": "La feuille de route des radiopharmaceutiques s'étend sur quatre-vingts ans, de l'iode radioactif pour le cancer de la thyroïde aux médicaments émetteurs alpha pour les cancers de la prostate et neuroendocrines, l'approvisionnement en isotopes étant le facteur limitant.",
  "rare-cancers": "Les cancers rares sont ceux qui comptent moins d'environ 6 nouveaux cas pour 100 000 personnes par an. Rares pris un par un, ils représentent ensemble un quart de tous les cancers et ont une survie moins bonne à cause du diagnostic tardif, du faible nombre d'essais et de l'expertise dispersée.",
  "mitotic-spindle-checkpoint": "Lorsqu'une cellule se divise, un échafaudage de microtubules (le fuseau) tire une copie de chaque chromosome vers chaque côté. Un point de contrôle retient la séparation jusqu'à ce que chaque chromosome soit accroché. Les taxanes et les alcaloïdes de la pervenche figent le fuseau, de sorte que la cellule reste bloquée à ce point de contrôle jusqu'à sa mort.",
  moffitt: "Moffitt est le centre de cancérologie de la Floride et le premier site américain pour la thérapie par TIL et la recherche sur la thérapie évolutive (« adaptative »).",
  "molecular-imaging-roadmap": "D'un traceur à base de sucre qui fait ressortir la plupart des cancers à des traceurs qui montrent une seule protéine, un type de cellule du stroma ou les cellules immunitaires à l'intérieur d'une tumeur.",
  "monoclonal-antibody": "Des protéines immunitaires fabriquées en laboratoire qui se fixent sur une seule cible, soit pour la bloquer, soit pour marquer la cellule afin qu'elle soit détruite.",
  "mount-sinai": "Mount Sinai est un centre universitaire de New York particulièrement fort en myélome et en immunologie du cancer.",
  "mr-linac": "Le MR-linac est un appareil de radiothérapie qui intègre une IRM, de sorte que le plan de traitement est ajusté à l'emplacement exact de la tumeur ce jour-là.",
  mrd: "Un cancer encore présent après le traitement mais trop petit pour être visible à l'imagerie, détecté par des analyses de sang ou de moelle osseuse.",
  "mrd-negative-cr": "Une rémission complète MRD négative signifie non seulement qu'aucune leucémie n'est visible au microscope, mais qu'aucune n'est détectable avec des tests mille fois plus sensibles. C'est l'objectif du traitement moderne de la leucémie.",
  "mrd-testing": "Une analyse de sang ultrasensible réalisée après la chirurgie, qui détecte le cancer résiduel des mois avant qu'une imagerie ne le fasse.",
  mri: "Utilise des aimants et des ondes radio, sans rayonnement, pour fournir des images très détaillées des tissus mous tels que le cerveau, le sein, le foie et la prostate.",
  msi: "L'instabilité des microsatellites est la marque d'un correcteur orthographique de l'ADN défaillant qui crée des milliers de mutations, rendant la tumeur très visible pour l'immunothérapie.",
  mskcc: "L'hôpital de cancérologie le mieux classé au monde, berceau du séquençage MSK-IMPACT, de l'étude du dostarlimab dans le cancer du rectum et de pionniers des CAR-T.",
  "multiple-endocrine-neoplasia": "Les syndromes MEN sont des anomalies héréditaires d'un seul gène qui provoquent des tumeurs dans plusieurs glandes hormonales au cours de la vie. Comme le gène peut être détecté dès l'enfance, les proches à risque peuvent être testés, surveillés et, dans le MEN2, se faire retirer la thyroïde avant l'apparition du cancer ; et pour le cancer de la thyroïde du MEN2 qui se propage malgré tout, il existe désormais un comprimé de précision, le selpercatinib, qui bloque la protéine RET défectueuse.",
  "mutagenesis-signatures": "Chaque cause de dommage à l'ADN laisse sa propre empreinte dans le génome : la lumière du soleil, le tabac, une enzyme de réparation défectueuse, une bactérie intestinale. Lire ces empreintes indique ce qui a causé un cancer et quelles équipes de réparation lui manquent, ce qui permet à son tour de prédire quels médicaments seront efficaces.",
  "mutational-signature": "Un motif caractéristique de mutations qui révèle leur cause : le tabac, les UV, un gène de réparation défectueux.",
  myc: "MYC est le gène du cancer le plus souvent amplifié, un interrupteur principal qui active des milliers de gènes de croissance. Il n'a pas de poche où un médicament classique pourrait se loger, si bien qu'il est resté « inaccessible aux médicaments » pendant 40 ans ; les premiers médicaments ciblant directement MYC sont enfin entrés en essais cliniques dans les années 2020.",
  "myeloid-suppression-axis": "Les tumeurs recrutent les cellules de nettoyage de l'organisme (macrophages et cellules myéloïdes immatures) et les rééduquent pour en faire leurs gardes du corps. Celles-ci désactivent les lymphocytes T, construisent des vaisseaux et, lorsqu'un anticorps thérapeutique marque une cellule cancéreuse pour qu'elle soit dévorée, reçoivent du CD47 présent à sa surface le message « ne me mange pas ».",
  "national-cancer-grid": "Un réseau de plus de 360 centres de cancérologie indiens, piloté depuis le Tata Memorial, qui s'accorde sur des recommandations de traitement communes, achète les médicaments anticancéreux en commun à une fraction du prix catalogue et organise des réunions de concertation et des essais cliniques partagés.",
  "ncc-hospital-east": "Le campus de Kashiwa du National Cancer Center du Japon, une place forte de la protonthérapie et des essais de phase précoce qui dirige SCRUM-Japan et de nombreux essais internationaux sur les cancers digestifs.",
  "ncc-japan": "Le National Cancer Center Hospital est le centre national de cancérologie du Japon et le premier site pour les essais des ADC DXd de Daiichi Sankyo.",
  nci: "Le NCI est l'agence de recherche sur le cancer du gouvernement américain ; il dépense environ 7 milliards de dollars par an et dirige le Cancer Centers Program, le TCGA et le laboratoire de thérapie cellulaire de Rosenberg.",
  "nci-cancer-centers": "Les centres de cancérologie désignés par le NCI constituent la liste, établie par le gouvernement américain, des centres qui répondent à ses normes de recherche et de soins.",
  "nci-ccr": "Les propres laboratoires et la clinique du NCI au NIH Clinical Center, siège de la branche de thérapie cellulaire de Rosenberg, du vaccin contre le HPV et de la génomique des lymphomes.",
  nejm: "Le NEJM est la revue médicale la plus influente. Lorsqu'un essai sur un médicament anticancéreux change la façon de traiter les patients, l'article paraît généralement ici, souvent publié le jour même de sa présentation à l'ASCO, à l'ESMO ou à l'ASH.",
  "neoadjuvant-adjuvant": "Les traitements néoadjuvant, adjuvant et périopératoire désignent respectivement un traitement administré avant la chirurgie, après la chirurgie, ou les deux.",
  neoantigen: "Un fragment de protéine créé par une mutation tumorale, que le système immunitaire n'a jamais rencontré auparavant, de sorte qu'il peut l'attaquer sans nuire aux cellules normales.",
  "neoantigen-mrna-vaccine": "Un vaccin fabriqué pour un seul patient, qui code les mutations uniques de sa propre tumeur, afin d'entraîner le système immunitaire à la traquer.",
  "ngs-mrd-clonoseq": "Séquencer le code-barres génétique unique de la leucémie d'un patient pour retrouver une cellule cancéreuse sur un million.",
  nice: "L'organisme d'évaluation des technologies de santé de l'Angleterre, qui décide si le NHS doit payer chaque nouveau médicament anticancéreux sur la base du coût par année de vie ajustée sur la qualité et gère le Cancer Drugs Fund.",
  niraparib: "Le niraparib est un inhibiteur de PARP approuvé en traitement d'entretien du cancer de l'ovaire quel que soit le statut BRCA, et dans le cancer de la prostate en association avec l'abiraterone.",
  nivolumab: "Nivolumab a été le deuxième bloqueur de PD-1 et il est souvent associé à ipilimumab. Les données à long terme montrent qu'environ la moitié des patients atteints d'un mélanome avancé sont encore en vie à 10 ans avec cette association.",
  "nk-cell-recognition": "Les cellules tueuses naturelles patrouillent à la recherche de cellules qui ont perdu leurs papiers d'identité (MHC-I) ou qui affichent des signaux de stress. Les cancers qui se cachent des cellules T en abandonnant le MHC-I deviennent visibles pour les cellules NK, à moins qu'ils ne se débarrassent aussi des signaux de stress, ne s'enveloppent d'un second badge inhibiteur (HLA-E) ou n'inondent leur voisinage de TGF-β.",
  nki: "Centre national néerlandais de lutte contre le cancer, pionnier en Europe de l'immunothérapie néoadjuvante (NADINA, NICHE) et de la thérapie par TIL.",
  novartis: "L'entreprise qui a fait de la thérapie par radioligands un véritable marché, avec Pluvicto et Lutathera, et le fabricant de Kisqali et de Gleevec.",
  "nrg-oncology": "Groupe coopératif américain issu de la fusion des groupes d'essais en radiothérapie, en gynécologie et en cancer du sein ; il a codirigé OlympiA, l'essai qui a instauré un inhibiteur de PARP après la chirurgie chez les porteurs d'une mutation BRCA.",
  ntrk: "Fusions de gènes rares retrouvées dans des dizaines de types de cancer ; la première cible pour laquelle un médicament a été approuvé pour toute tumeur qui la porte.",
  "nutrient-competition-tme": "Les tumeurs et les cellules immunitaires mangent dans la même assiette. Les cellules cancéreuses accaparent le glucose et la glutamine, rejettent du lactate et de l'acide, et brûlent le tryptophane et l'arginine en sous-produits qui paralysent les cellules T. La tumeur gagne la bataille pour la nourriture, et le système immunitaire perd avant même d'avoir tiré un coup.",
  "nutrition-lifestyle": "Ce que les gens mangent, boivent, pèsent et font influence qui développe un cancer, comment se déroule le traitement et qui rechute. Ce front étudie tout cela avec la rigueur d'un essai de médicament.",
  "nutrition-screening-mnt": "Le dépistage nutritionnel consiste à peser chaque patient, à poser quelques questions de dépistage et à orienter les personnes à risque vers un diététicien. C'est simple, recommandé par les guides de pratique, et pourtant toujours pas fait de façon systématique.",
  "obesity-related-cancers": "L'excès de graisse corporelle est une cause établie d'au moins 13 cancers, dont ceux de l'utérus, de l'œsophage, du rein, du foie, de l'intestin, du pancréas et le cancer du sein après la ménopause. Dans de nombreux pays, c'est la deuxième cause évitable de cancer après le tabac.",
  obinutuzumab: "Obinutuzumab est un anticorps anti-CD20 renforcé qui, associé au venetoclax pendant un an, permet à de nombreux patients atteints de CLL de passer des années sans aucun traitement.",
  oeci: "Le réseau des centres européens de lutte contre le cancer qui gère le programme d'accréditation et de désignation attribuant le statut de « Comprehensive Cancer Centre ».",
  olaparib: "Olaparib a été le premier inhibiteur de PARP et a transformé la mutation BRCA héréditaire d'un facteur de risque en une cible médicamenteuse, y compris après la chirurgie dans le cancer du sein.",
  oligometastatic: "Cancer qui ne s'est propagé qu'à quelques endroits et qui peut encore être guérissable en traitant chaque foyer.",
  "oncogene-activation-two-hit": "Parmi les milliers de mutations présentes dans une tumeur, seule une poignée (généralement 2 à 8) la fait réellement avancer. Ces mutations « conductrices » soit bloquent un accélérateur en position enfoncée (oncogènes, un seul coup suffit), soit suppriment un frein (suppresseurs de tumeur, les deux copies doivent disparaître). Tout le reste n'est que passager embarqué pour le voyage.",
  "oncogene-addiction": "Lorsqu'un cancer dépend si complètement d'un seul gène muté que le bloquer fait s'effondrer la tumeur.",
  "oncogenic-viruses": "Environ un cancer sur huit dans le monde est causé par un virus. HPV, hépatites B et C, Epstein-Barr, HTLV-1, KSHV et polyomavirus des cellules de Merkel détournent chacun les mêmes freins que le cancer doit normalement faire muter, ce qui explique pourquoi les vaccins contre HPV et HBV figurent parmi les médicaments anticancéreux les plus efficaces jamais créés.",
  "oncology-real-world-data": "Bases de données constituées à partir de millions de dossiers de patients réels, utilisées pour voir comment les traitements fonctionnent en dehors des essais et pour mener des études sans lancer de nouveaux essais.",
  "oncolytic-virus": "Virus modifiés pour infecter et faire éclater les cellules cancéreuses tout en épargnant les cellules normales, et pour alerter le système immunitaire au passage.",
  "oncotype-dx": "Un test de 21 gènes qui indique à la plupart des femmes atteintes d'un cancer du sein précoce hormonosensible si elles peuvent se passer de chimiothérapie en toute sécurité.",
  optune: "Optune est un dispositif portable qui délivre des champs électriques perturbant la division cellulaire. Il est approuvé pour le glioblastome et, en 2026, pour le cancer du pancréas.",
  "organ-tropism-seed-soil": "Le cancer du sein va vers l'os, le poumon, le foie et le cerveau ; le cancer de la prostate vers l'os ; le cancer du côlon vers le foie ; le mélanome uvéal presque uniquement vers le foie. L'idée de Paget, formulée en 1889, reste valable : l'endroit où un cancer se propage dépend à la fois de la graine (le programme de la cellule) et du sol (l'accueil réservé par l'organe). Chaque sol a son propre cercle vicieux, et certains peuvent être ciblés par des médicaments.",
  organoids: "Les organoïdes dérivés de patients sont des versions miniatures en 3D de la tumeur d'un patient, cultivées en laboratoire.",
  orr: "Le taux de réponse objective (ORR) est le pourcentage de patients dont les tumeurs diminuent d'au moins 30 %.",
  os: "La survie globale (OS) mesure combien de temps les patients vivent, tout simplement. C'est le critère d'évaluation de référence.",
  osimertinib: "Osimertinib (Tagrisso) est le comprimé de référence pour le cancer du poumon avec mutation EGFR, désormais aussi donné après la chirurgie et avec une chimiothérapie ou après une chimioradiothérapie.",
  "p53-cell-cycle": "Les points de contrôle p53 et RB sont les freins de la cellule. p53 détecte les dommages et empêche la cellule de se copier ; RB retient la cellule à la porte G1 jusqu'à ce que CDK4/6 la déverrouille. Les cancers coupent ces freins.",
  "p53-mdm2-axis": "p53 est le coordinateur d'urgence de la cellule. Les dommages, le stress lié aux oncogènes ou le manque d'oxygène l'activent ; il met alors la division en pause, ordonne des réparations, ou déclenche le suicide cellulaire ou la retraite définitive. MDM2 le maintient éteint dans les cellules saines. La moitié de tous les cancers cassent p53 purement et simplement ; beaucoup des autres surproduisent MDM2.",
  paclitaxel: "Un poison des microtubules découvert dans l'if du Pacifique, l'une des chimiothérapies les plus utilisées dans les cancers du sein, du poumon et de l'ovaire.",
  "paediatric-germ-cell-tumours": "Les tumeurs germinales naissent des cellules destinées à devenir des ovules ou des spermatozoïdes et peuvent apparaître dans les gonades, le bas du dos, le thorax ou le cerveau. Elles comptent parmi les cancers de l'enfant les plus guérissables, car elles répondent à la chimiothérapie par cisplatin et libèrent des marqueurs sanguins qui facilitent la surveillance. Le travail consiste désormais à guérir avec moins : la chirurgie seule pour les tumeurs à faible risque, des dérivés du platine plus doux et la protection de l'audition.",
  sinonasal: "Les cancers du nez et des sinus forment un groupe hétérogène, allant du carcinome épidermoïde à l'esthésioneuroblastome, d'origine nerveuse, et au carcinome indifférencié agressif SNUC. La chirurgie par le nez à l'aide d'un endoscope suivie d'une radiothérapie précise a remplacé les opérations ouvertes défigurantes, et le fait de donner d'abord une chimiothérapie pour voir qui y répond guide désormais la façon de traiter le SNUC.",
  "siop-europe": "La société européenne d'oncologie pédiatrique et l'organisation faîtière des groupes européens d'essais cliniques qui traitent la plupart des enfants atteints de cancer selon des protocoles communs.",
  sitc: "La société des immunologistes du cancer et des immuno-oncologues, dont le congrès annuel, les recommandations et les ressources sur la prise en charge des effets indésirables d'origine immunitaire accompagnent l'ère de l'immunothérapie.",
  "site-specific-conjugation": "La conjugaison site-spécifique et la chimie des linkers déterminent exactement où et combien de charges actives se fixent sur l'anticorps, ce qui conditionne la sécurité et l'efficacité d'un ADC.",
  "small-bowel": "Les cancers de l'intestin grêle sont rares et souvent découverts tard, car l'intestin grêle est difficile à examiner et les symptômes sont vagues. La chirurgie guérit la maladie précoce, la chimiothérapie empruntée au cancer du côlon aide après la chirurgie et dans la maladie avancée, et une minorité importante de tumeurs présente un défaut de réparation de l'ADN qui les rend très sensibles à l'immunothérapie.",
  sorafenib: "Le tout premier médicament à avoir prolongé la vie dans le cancer du foie avancé (2007), aujourd'hui surtout utilisé comme bras de comparaison face auquel on mesure les combinaisons plus récentes.",
  sotorasib: "Sotorasib (Lumakras) a été le premier médicament à cibler KRAS, approuvé en 2021 après quatre décennies d'échecs.",
  sstr2: "Le récepteur de la somatostatine de type 2 est un récepteur hormonal très abondant à la surface des tumeurs neuroendocrines, et il a été la première cible théranostique à entrer dans les soins courants.",
  "st-jude": "Le seul centre de cancérologie complet reconnu par le NCI entièrement consacré aux enfants, où les protocoles Total Therapy ont rendu la leucémie de l'enfant guérissable ; les familles ne reçoivent jamais de facture pour les soins.",
  "stage-shift": "Le décalage de stade signifie détecter plus de cancers à un stade précoce et moins à un stade tardif ; c'est l'objectif mesurable du dépistage.",
  "standard-of-care": "Le standard de soins est le traitement que les recommandations et les experts considèrent actuellement comme l'option la mieux démontrée.",
  stanford: "Stanford est le berceau de l'innovation en CAR-T (Mackall, Majzner), de la découverte de CD47 (Weissman) et de l'intelligence artificielle en médecine.",
  sunitinib: "Sunitinib est un comprimé anti-angiogénique approuvé pour les tumeurs neuroendocrines du pancréas, le cancer du rein et les GIST.",
  "supportive-care": "Les soins de support et l'après-cancer recouvrent tout ce qui permet au patient d'être assez bien pour recevoir son traitement, et de rester bien ensuite.",
  surgery: "Retirer ou détruire physiquement les tumeurs, de plus en plus avec des robots, un guidage par l'image, et de la chaleur ou du froid à la place du bistouri.",
  "survivorship-care-plan": "Un suivi organisé pour les 18 millions de survivants du cancer aux États-Unis et les plus de 50 millions dans le monde : surveiller les récidives et les seconds cancers, prendre en charge les effets secondaires à long terme comme les atteintes cardiaques, l'infertilité, la neuropathie et la fatigue, et aider les personnes à reprendre le travail et leur vie.",
  swog: "SWOG est l'un des groupes coopératifs du US National Cancer Institute : des milliers de centres communautaires et universitaires menant des essais qui changent la pratique, dont le résultat de 2026 dans le lymphome de Hodgkin en première ligne.",
  "synthetic-lethality": "Deux gènes dont la perte de l'un ou de l'autre seul est sans conséquence, mais dont la perte des deux tue la cellule. Les cancers qui ont perdu l'un des deux deviennent vulnérables aux médicaments dirigés contre l'autre.",
  "synthetic-lethality-approaches": "Trouver un deuxième gène dont un cancer a besoin uniquement parce que son premier gène est défaillant, puis cibler ce deuxième gène.",
  "synthetic-lethality-map": "Deux gènes sont dits synthétiquement létaux lorsque la perte de l'un ou de l'autre seul est sans conséquence, mais que la perte des deux tue la cellule. Les cancers qui en ont déjà perdu un (un suppresseur de tumeur qu'on ne peut pas restaurer) deviennent particulièrement dépendants de l'autre, que l'on peut cibler par un médicament. BRCA et PARP en ont été la première preuve ; une douzaine d'autres paires sont aujourd'hui en essais cliniques.",
  "systemic-mastocytosis": "La mastocytose systémique est une maladie clonale des mastocytes, les cellules immunitaires qui libèrent l'histamine ; presque tous les cas sont dus à une seule mutation du gène KIT. Des comprimés qui bloquent précisément KIT réduisent désormais la masse de mastocytes, soulagent les symptômes et, dans les formes agressives, prolongent la vie. La plupart des patients ont la forme indolente, où l'objectif est de contrôler les symptômes et de prévenir l'anaphylaxie.",
  sysucc: "Sun Yat-sen University Cancer Center est l'un des plus grands centres de cancérologie de Chine, le leader mondial du carcinome du nasopharynx et l'un des principaux recruteurs pour les essais chinois d'ADC et de PD-1.",
  "t-cell": "Les tueurs entraînés du système immunitaire. Chaque lymphocyte T reconnaît une cible précise présentée à la surface d'une cellule et, si cette cellule est infectée ou cancéreuse, la tue. L'immunothérapie consiste en grande partie à les libérer.",
  "t-cell-engager": "Un médicament prêt à l'emploi qui relie physiquement un lymphocyte T tueur à une cellule cancéreuse, forçant l'attaque.",
  "t-cell-exhaustion": "Les lymphocytes T qui font face à leur cible pendant des semaines sans l'emporter s'éteignent progressivement : ils activent une série de freins (PD-1, LAG-3, TIM-3, TIGIT), perdent leur capacité à tuer et finissent par verrouiller cet état dans leur ADN. Les médicaments anti-checkpoint sauvent ceux qui ne sont que partiellement épuisés ; ceux qui sont épuisés de façon terminale sont hors de portée.",
  takeda: "Takeda codétient Adcetris en dehors des États-Unis et développe des conjugués agonistes de STING et des cellules CAR-NK.",
  talazoparib: "Talazoparib est le piégeur de PARP le plus puissant, approuvé dans le cancer du sein lié à BRCA et, en association avec enzalutamide, dans le cancer de la prostate.",
  "talicabtagene-autoleucel": "La première thérapie cellulaire CAR-T conçue en Inde même, approuvée en 2023 pour la leucémie et le lymphome en rechute, fabriquée à Mumbai pour environ un dixième de ce que coûte le même type de traitement aux États-Unis.",
  tamoxifen: "Le tout premier médicament anticancéreux ciblé (1977) : un comprimé qui bloque l'effet des œstrogènes sur le cancer du sein et réduit de moitié les récidives, toujours essentiel pour les femmes avant la ménopause.",
  "targeted-alpha-therapy": "Comme la thérapie par radioligand mais avec des particules alpha : bien plus destructrices sur une portée beaucoup plus courte, ce qui permet de tuer des cellules isolées avec moins de dommages collatéraux.",
  "tumor-microenvironment": "Une tumeur n'est pas seulement un amas de cellules cancéreuses. C'est un voisinage de fibroblastes, de cellules immunitaires, de vaisseaux sanguins, de nerfs et de tissu de soutien que le cancer recrute et corrompt, et qui décide si les médicaments et les cellules immunitaires peuvent y pénétrer.",
  "tumour-agnostic": "Une approbation agnostique de la tumeur permet d'utiliser un médicament pour tout cancer porteur d'une caractéristique moléculaire précise, quel que soit l'organe où il a débuté.",
  "ubiquitin-proteasome-system": "Les cellules marquent les protéines indésirables avec une petite étiquette appelée ubiquitine et les envoient dans un broyeur, le protéasome. Les cellules de myélome, qui fabriquent des anticorps en masse, meurent si le broyeur se bloque ; et les médicaments les plus récents détournent la machinerie d'étiquetage pour forcer le cancer à détruire ses propres oncoprotéines.",
  "uchicago-cancer": "C'est là que Charles Huggins a prouvé que les hormones alimentent le cancer de la prostate et que Janet Rowley a découvert les translocations chromosomiques à l'origine de la leucémie ; aujourd'hui, le centre est fort en immunologie des tumeurs.",
  "ucla-jonsson": "C'est là que trastuzumab (Slamon) et palbociclib ont été développés sur le plan clinique ; le centre est aussi un leader du PET PSMA et de l'immunothérapie du mélanome (Ribas).",
  uclh: "L'hôpital universitaire du centre de Londres et l'un des deux centres de protonthérapie du NHS, soutenu par l'institut du cancer de l'UCL et ses recherches sur les CAR-T et l'évolution du cancer du poumon.",
  "ucsd-moores": "Le centre de cancérologie intégré du NCI à San Diego, où ont été développés l'anticorps anti-GD2 dinutuximab et l'anticorps anti-ROR1 à l'origine de zilovertamab.",
  ucsf: "L'UCSF est le berceau de la biologie des oncogènes (Bishop, Varmus) et du ciblage médicamenteux de KRAS G12C (Shokat), et un leader des essais adaptatifs I-SPY dans le cancer du sein.",
  ultrasound: "L'échographie utilise des ondes sonores pour produire des images en direct ; elle est peu coûteuse, sûre et sert à guider les aiguilles jusque dans les masses.",
  unicancer: "UNICANCER est le réseau des centres de lutte contre le cancer français et le promoteur de leurs essais académiques.",
  "unproven-diet-claims": "Régimes vendus comme des remèdes ou des moyens de prévention contre le cancer sans aucune preuve à l'appui : régimes alcalins, cures de jus, thérapie Gerson, noyaux d'abricot et autres. Certains sont simplement inutiles ; plusieurs ont causé des dommages ou conduit des personnes à retarder un traitement efficace.",
  urethral: "Le cancer de l'urètre se développe dans le conduit qui évacue l'urine hors du corps. Il est très rare, si bien que les médecins le traitent en s'inspirant du cancer de la vessie, du cancer de l'anus et du cancer de la vulve selon le type de cellules et la localisation. Associer la chimiothérapie à la radiothérapie avant la chirurgie, ou à sa place, permet à davantage de patients de conserver leurs organes.",
  "uterine-sarcoma": "Les sarcomes utérins sont des cancers rares du muscle et du tissu de soutien de l'utérus, distincts du cancer de l'endomètre, bien plus fréquent. L'ablation de l'utérus en un seul bloc est le traitement principal et guérit de nombreuses tumeurs précoces ; les sarcomes du stroma de bas grade répondent aux comprimés bloquant les hormones, tandis que le léiomyosarcome avancé est traité par chimiothérapie, comme doxorubicin et trabectedin.",
  "uz-leuven": "Le plus grand hôpital universitaire de Belgique et un centre de cancérologie intégré accrédité par l'OECI, avec une recherche de classe mondiale en cancérologie digestive, gynécologique et sur l'angiogenèse.",
  vaginal: "Le cancer primitif du vagin est rare et le plus souvent causé par le HPV, le virus à l'origine du cancer du col de l'utérus. Il se traite comme le cancer du col, par une chimiothérapie associée à une radiothérapie externe et interne, ce qui guérit de nombreuses patientes tout en préservant l'organe. La vaccination contre le HPV et le dépistage du col de l'utérus, qui détecte aussi les lésions précancéreuses vaginales, le font régulièrement reculer.",
  "vascular-tumours": "Les tumeurs vasculaires vont de l'angiosarcome, un cancer agressif des cellules qui tapissent les vaisseaux sanguins, à l'EHE à croissance lente et au KHE, une tumeur du nourrisson. L'angiosarcome répond à la chimiothérapie par paclitaxel et, dans sa forme du cuir chevelu abîmé par le soleil, à l'immunothérapie ; l'EHE et le KHE sont entretenus par des signaux de croissance que le bloqueur de mTOR sirolimus peut calmer, et de nombreux cas d'EHE peuvent simplement être surveillés.",
  vegf: "Le signal que les tumeurs utilisent pour se fabriquer leur propre réseau sanguin. Le bloquer affame les tumeurs et, de façon surprenante, aide l'immunothérapie à agir.",
  "vegf-angiogenesis": "Comment les tumeurs se fabriquent leur propre réseau sanguin. Le manque d'oxygène pousse les cellules à libérer du VEGF, qui ordonne aux cellules des vaisseaux sanguins de bourgeonner vers la tumeur.",
  vemurafenib: "Vemurafenib a été le premier inhibiteur de BRAF (2011) ; il a fait régresser des mélanomes en quelques semaines et prouvé qu'une seule mutation pouvait être ciblée par un médicament dans une tumeur solide.",
  venetoclax: "Un comprimé qui retire aux cellules leucémiques leur bouclier de survie, permettant un traitement de la CLL sans chimiothérapie et de durée limitée.",
  vincristine: "Une chimiothérapie d'origine végétale, tirée de la pervenche de Madagascar, présente dans presque tous les protocoles de traitement des leucémies et lymphomes de l'enfant depuis les années 1960.",
  "virtual-cell": "La tentative de construire un modèle informatique d'une cellule assez fidèle pour prédire l'effet d'un médicament ou d'une mutation avant même que quiconque ne réalise l'expérience.",
  wee1: "Une kinase de point de contrôle qui laisse aux cellules le temps de réparer leur ADN avant de se diviser. La supprimer force les cellules cancéreuses endommagées à entrer dans une division qui leur est fatale.",
  "wellcome-sanger": "L'institut britannique de génomique dont le Cancer Genome Project a découvert la mutation de BRAF dans le mélanome, créé COSMIC et défini les signatures mutationnelles.",
  "wes-wgs": "Lire tous les gènes (exome) ou la totalité de l'ADN (génome) d'une tumeur, plutôt qu'un panel de gènes choisis.",
  wnt: "Wnt/β-catenin est une voie du développement détournée par le cancer colorectal. Normalement, un complexe de destruction maintient la β-catenin à un niveau bas ; la perte d'APC lui permet d'envahir le noyau et d'activer les gènes de croissance.",
  "y-combinator": "Y Combinator est l'accélérateur de start-up qui finance chaque année des centaines de nouvelles entreprises en échange d'une petite participation. Depuis 2014, il soutient un flux régulier d'entreprises qui s'attaquent au cancer, des tests sanguins aux virus modifiés.",
  zanidatamab: "Zanidatamab (Ziihera) est un anticorps qui s'accroche à HER2 en deux endroits différents, approuvé pour le cancer des voies biliaires HER2+.",
  zanubrutinib: "Zanubrutinib est le seul bloqueur de BTK à avoir surpassé ibrutinib à la fois en efficacité et en sécurité dans un essai comparatif direct. C'est aujourd'hui l'inhibiteur de BTK le plus prescrit dans la CLL.",
  ziftomenib: "Ziftomenib est le deuxième inhibiteur de menin pour la leucémie, approuvé en novembre 2025 sous forme de comprimé en une prise quotidienne pour l'AML en rechute avec mutation de NPM1.",
  // ---- second wave (2026-09) ----
  "12-de-octubre": "L'un des plus grands hôpitaux de Madrid, un site de premier plan pour les essais sur le cancer du poumon et le myélome et pour le développement académique de CAR-T.",
  aall1731: "Chez les enfants atteints d'une leucémie de risque moyen, l'ajout de blinatumomab a fait passer la survie sans maladie à trois ans de 88% à 96%, l'un des plus grands gains depuis des décennies.",
  "aarhus-university-hospital": "Le deuxième hôpital universitaire du Danemark, siège du centre national de protonthérapie et des essais DAHANCA de radiothérapie des cancers de la tête et du cou.",
  abcsg: "Le groupe académique autrichien d'essais sur les cancers du sein et colorectal, dont les essais sur les traitements ciblant l'os et l'hormonothérapie prolongée ont changé la pratique dans le cancer du sein.",
  "abscopal-effect": "Lorsque l'irradiation d'une tumeur fait régresser des tumeurs non traitées situées ailleurs, par l'intermédiaire du système immunitaire.",
  "ac225-psma": "Des médicaments PSMA émetteurs alpha qui produisent des réponses même après l'échec de Pluvicto, freinés surtout par l'approvisionnement en isotope.",
  "accelerate-platform": "Un forum basé à Bruxelles où médecins du cancer de l'enfant, laboratoires pharmaceutiques, régulateurs et parents s'accordent sur la manière de tester les nouveaux médicaments anticancéreux chez l'enfant, afin que moins de médicaments prometteurs laissent de côté les cancers pédiatriques.",
  "active-surveillance-term": "Ne pas traiter volontairement un cancer pour l'instant, mais le surveiller régulièrement par des analyses de sang, des examens d'imagerie ou des biopsies, et ne traiter que s'il montre des signes de progression. C'est la norme pour le cancer de la prostate à faible risque, les petites masses rénales et plusieurs autres affections d'évolution lente.",
  adaura: "A montré qu'un comprimé ciblé après une chirurgie du cancer du poumon divise par deux le risque de décès, le premier résultat de ce type pour une thérapie ciblée.",
  "adc-cdmo-manufacturing": "Relier une charge hautement toxique à un anticorps de façon sûre et à grande échelle. Peu de sous-traitants savent le faire, ce qui détermine qui peut développer des ADC.",
  adcc: "Dans l'ADCC, un anticorps marque une cellule, et les cellules NK reconnaissent ce marquage et la tuent.",
  "aditya-bardia": "A dirigé ASCENT, l'essai qui a fait du sacituzumab govitecan le premier ADC pour le cancer du sein triple négatif, et l'essai EMERALD de l'elacestrant.",
  "afamitresgene-autoleucel": "Afamitresgene autoleucel a été la première thérapie par récepteur de lymphocytes T modifié approuvée pour une tumeur solide, le sarcome synovial.",
  agitg: "Le groupe d'essais sur les cancers digestifs d'Australie et de Nouvelle-Zélande, qui mène des essais influençant la pratique dans les cancers de l'estomac, de l'œsophage, colorectal et du pancréas, y compris des études adjuvantes guidées par le ctDNA.",
  "aiims-delhi": "La première institution médicale publique de l'Inde, dont le Rotary Cancer Hospital et le nouveau campus du National Cancer Institute à Jhajjar sont les piliers de la recherche et des soins publics en cancérologie.",
  ak146d1: "AK146D1 est l'ADC bispécifique Nectin-4 × TROP2 d'Akeso, qui réunit les deux cibles d'ADC les plus validées en une seule molécule.",
  akeso: "Biotech chinoise dont l'ivonescimab a battu Keytruda en comparaison directe, et développeur de l'ADC Nectin-4×TROP2.",
  "alcohol-reduction-labelling": "L'alcool cause au moins sept cancers et il n'existe pas de seuil sans risque. Le prix, la disponibilité et les étiquettes d'avertissement sur le cancer sont les outils qui fonctionnent ; la plupart des gens ignorent encore que l'alcool cause le cancer.",
  "alliance-oncology": "Groupe coopératif américain né de la fusion de CALGB, ACOSOG et NCCTG ; il mène OptimICE-pCR, qui demande si les patientes atteintes de TNBC ayant obtenu une réponse complète ont encore besoin d'un an d'immunothérapie.",
  "alpha-vs-beta": "Les particules bêta (lutétium-177) parcourent quelques millimètres et conviennent aux maladies volumineuses ; les particules alpha (actinium-225) parcourent la largeur de quelques cellules et tuent avec une énergie bien plus élevée.",
  "alternative-medicine-instead-of-treatment": "Les approches complémentaires utilisées en parallèle du traitement peuvent aider à soulager les symptômes. Choisir une thérapie alternative à la place de la chirurgie, de la chimiothérapie, de la radiothérapie ou de l'hormonothérapie est une décision différente : dans une base de données nationale américaine, les personnes qui l'ont fait avaient deux fois et demie plus de risque de mourir pendant la période de l'étude, et plus de cinq fois plus en cas de cancer du sein.",
  amplify: "AMPLIFY est l'essai à l'origine du premier traitement de la CLL entièrement par voie orale et de durée fixe approuvé aux États-Unis (février 2026) : 14 cycles de deux comprimés, puis arrêt.",
  anlotinib: "Anlotinib est l'un des comprimés anticancéreux les plus utilisés en Chine, d'abord approuvé pour le cancer du poumon après échec d'autres traitements, puis pour plusieurs tumeurs plus rares.",
  anthracycline: "Une famille de médicaments de chimiothérapie de couleur rouge, dérivés d'une bactérie du sol, qui endommagent l'ADN du cancer. Piliers du traitement du cancer du sein, du lymphome, de la leucémie et du sarcome, mais ils affaiblissent le cœur de façon dose-dépendante, d'où une limite à vie.",
  antibody: "Une protéine en forme de Y que le système immunitaire fabrique pour s'accrocher à une cible précise. Les anticorps fabriqués sont aujourd'hui une pierre angulaire du traitement du cancer, soit en bloquant une protéine, soit en lui apportant une charge.",
  "antiemetic-therapy": "Les médicaments grâce auxquels la chimiothérapie ne rime plus avec des jours de vomissements : bloqueurs 5-HT3 (ondansetron, palonosetron), bloqueurs NK1 (aprepitant), dexaméthasone et olanzapine, administrés selon le risque émétique de chaque protocole.",
  antigen: "Tout ce qu'un anticorps ou une cellule immunitaire peut reconnaître, généralement une protéine à la surface d'une cellule. Dans le cancer, un antigène est le drapeau qui indique à un médicament ou à une cellule immunitaire « voici la cellule à attaquer ».",
  "arcagy-gineco": "Le groupe français d'essais en cancérologie gynécologique qui a mené PAOLA-1, l'essai ajoutant l'olaparib au bevacizumab en entretien dans le cancer de l'ovaire.",
  "aromatase-inhibitor": "Des comprimés qui empêchent le corps de produire des œstrogènes (après la ménopause, quand ils proviennent de la graisse et du muscle plutôt que des ovaires), privant ainsi le cancer du sein à récepteurs hormonaux positifs de son carburant. Pris pendant cinq à dix ans après la chirurgie, ils réduisent de moitié les récidives.",
  "artera-ai-prostate": "Le premier outil d'IA autorisé par la FDA pour prédire à la fois le pronostic et le bénéfice du traitement à partir d'une lame de biopsie de routine, dans le cancer de la prostate.",
  "asan-medical-center": "Asan Medical Center est le plus grand hôpital de Corée et un leader mondial de la transplantation hépatique et de la chirurgie du cancer de l'estomac.",
  asciminib: "Asciminib est un bloqueur de BCR::ABL1 qui se fixe sur une poche différente de celle de tous les autres TKI, approuvé en 2024 pour toute leucémie myéloïde chronique nouvellement diagnostiquée et désormais testé dans la ALL Ph positive.",
  ash: "La plus grande société d'hématologie au monde, dont le congrès annuel de décembre est le lieu où sont présentés pour la première fois les résultats décisifs dans la leucémie, le lymphome et le myélome.",
  astellas: "Astellas codétient Padcev et fabrique Vyloy, le premier médicament ciblant Claudin 18.2.",
  astro: "La plus grande société de radiothérapie oncologique, dont le congrès annuel, les recommandations et les listes Choosing Wisely favorisent l'adoption de l'hypofractionnement et de la radiothérapie stéréotaxique.",
  "augment-101": "L'essai qui a fait passer l'inhibition de la ménine du stade d'idée au premier médicament approuvé pour la leucémie avec réarrangement de KMT2A.",
  "auto-contouring-ai": "Un logiciel qui délimite automatiquement les organes et les tumeurs sur les images, faisant gagner des heures par patient et rendant l'adaptation quotidienne du plan réalisable en pratique.",
  "autogene-cevumeran": "Le vaccin personnalisé de BioNTech, remarqué pour une petite étude dans le cancer du pancréas où les patients ayant répondu au vaccin sont restés sans cancer pendant des années.",
  "autologous-transplant": "Une chimiothérapie à très forte dose qui détruirait la moelle osseuse, rendue supportable en réinjectant au patient ses propres cellules souches prélevées auparavant. Standard dans le myélome et le lymphome en rechute ; les cellules sauvent la moelle, elles ne combattent pas le cancer.",
  avapritinib: "Avapritinib est le premier médicament contre les GIST portés par la mutation PDGFRA D842V, qui résiste à tous les autres inhibiteurs de kinase ; il est aussi approuvé dans la mastocytose systémique.",
  avelumab: "Avelumab est un bloqueur de PD-L1 administré en entretien après la chimiothérapie dans le cancer de la vessie avancé, qui a prolongé la survie d'environ sept mois.",
  "avoiding-immune-destruction": "Les cancers se cachent du système immunitaire ou le désactivent, en perdant les molécules qui présentent leurs antigènes ou en renforçant les freins des points de contrôle.",
  axitinib: "Axitinib est un comprimé sélectif contre le récepteur du VEGF, désormais donné surtout avec pembrolizumab ou avelumab en traitement de première ligne du cancer du rein.",
  "aya-oncology": "Le cancer chez les personnes de 15 à 39 ans, environ 90 000 cas par an aux États-Unis, avec un éventail de cancers particulier, une amélioration de la survie plus lente que chez les enfants ou les adultes plus âgés, et des besoins spécifiques : fertilité, études et travail, soutien psychosocial et accès aux essais.",
  "b-cell": "Les cellules immunitaires qui fabriquent les anticorps. Elles comptent doublement dans le cancer : comme source de tout anticorps thérapeutique, et comme cellules qui déraillent dans la plupart des lymphomes, des leucémies et du myélome.",
  "bariatric-surgery-cancer-incidence": "Les personnes souffrant d'obésité sévère qui subissent une chirurgie de l'obésité développent environ un tiers de cancers en moins au cours de la décennie suivante, en particulier des cancers de l'utérus et d'autres cancers hormono-dépendants, par rapport à des personnes similaires non opérées.",
  "basement-membrane-tissue-barriers": "Chaque organe maintient ses cellules de revêtement derrière une fine et dense couche de protéines appelée membrane basale. Une tumeur qui ne l'a pas franchie est 'in situ' et essentiellement curable ; la franchir est le moment où le cancer devient invasif.",
  bayer: "Bayer détient Xofigo, le seul émetteur alpha approuvé, et développe des agents PSMA à l'actinium de nouvelle génération.",
  "bc-cancer": "L'agence provinciale du cancer de la Colombie-Britannique, leader mondial en génomique du cancer (Personalized OncoGenomics), en recherche sur le lymphome et en dépistage du col de l'utérus basé sur le HPV.",
  "bcg-intravesical": "Un vaccin atténué contre la tuberculose instillé directement dans la vessie. Depuis 1976, c'est le traitement le plus efficace du cancer précoce de la vessie, et il reste en pénurie chronique.",
  "bcg-unresponsive": "La définition par la FDA du cancer de la vessie précoce ayant échoué à un traitement adéquat par BCG, la population dans laquelle la plupart des nouveaux médicaments de la vessie sont d'abord approuvés.",
  "bclc-staging": "Le système de stadification du cancer du foie qui combine la taille de la tumeur, la fonction hépatique et l'état général pour recommander un traitement : ablation ou chirurgie, transplantation, TACE ou médicaments.",
  "bcr-abl1-signalling": "La leucémie myéloïde chronique est causée par un seul gène cassé : deux chromosomes échangent des morceaux et collent une kinase (ABL1) à une protéine qui la force à rester allumée en permanence. Imatinib, le premier médicament à la cibler, a transformé une maladie mortelle en maladie gérable, et des médicaments ultérieurs couvrent les mutations qui lui échappent.",
  "bcr-signalling": "Le récepteur des cellules B est l'interrupteur de survie des cellules B. Ses signaux passent par BTK pour libérer NF-kappa-B, qui maintient la cellule en vie. Les cancers des cellules B le gardent allumé ; les inhibiteurs de BTK, les inhibiteurs du protéasome et le lénalidomide coupent la ligne chacun à un point différent.",
  bcrf: "Le plus grand financeur privé de la recherche sur le cancer du sein au monde, qui accorde chaque année des subventions à plus de 250 chercheurs dans les principaux centres du domaine.",
  "beatson-glasgow": "Le plus grand centre de cancérologie d'Écosse, qui porte le nom du chirurgien ayant utilisé pour la première fois l'hormonothérapie contre le cancer du sein, à côté d'un institut de biologie du cancer de premier plan.",
  "belantamab-mafodotin": "Un ADC contre le myélome retiré du marché en 2022, puis revenu en 2025 après des essais solides dans des lignes de traitement plus précoces.",
  beone: "BeOne Medicines fabrique Brukinsa, le premier inhibiteur de BTK du marché, et tislelizumab, et est le partenaire asiatique pour zanidatamab.",
  "bgb-16673": "Au lieu de bloquer BTK, ce comprimé le détruit, de sorte qu'il agit même lorsque l'enzyme a muté pour échapper à tous les inhibiteurs.",
  "bh3-profiling": "Un test de laboratoire qui mesure à quel point une cellule leucémique est proche de s'autodétruire, et quelle protéine de survie la retient, afin de prédire la réponse aux médicaments de type venetoclax.",
  big: "Le Breast International Group est la structure qui fédère plus de 50 groupes académiques de recherche sur le cancer du sein dans le monde et le co-promoteur d'OlympiA, APHINITY et HERA.",
  biocon: "La plus grande entreprise biopharmaceutique d'Inde, fondée par Kiran Mazumdar-Shaw en 1978, et maison mère de Biocon Biologics, qui fabrique des copies à bas coût des anticorps trastuzumab et bevacizumab.",
  biomarker: "Tout ce qui est mesurable dans le corps ou la tumeur et qui apporte une information utile : de quel type de cancer il s'agit, comment il risque d'évoluer, ou quel médicament a des chances d'être efficace.",
  biontech: "Du vaccin contre la COVID à un large portefeuille en oncologie : vaccins personnalisés, ADC venus de Chine et un bispécifique PD-L1×VEGF vendu à BMS pour 11 milliards de dollars.",
  biosimilar: "Un biosimilaire est une copie d'un médicament biologique comme le trastuzumab, dont il a été démontré qu'il est aussi sûr et efficace que l'original une fois son brevet expiré, généralement à un prix inférieur.",
  "birmingham-cancer-centre": "Le centre anticancéreux de la deuxième ville d'Angleterre, siège de l'une des plus grandes unités universitaires d'essais en cancérologie du Royaume-Uni et de grands essais sur les cancers de la vessie, colorectaux et pédiatriques.",
  bleomycin: "Bleomycin est le « B » de BEP pour le cancer du testicule et d'ABVD pour le lymphome de Hodgkin ; son danger propre est la fibrose des poumons, on surveille donc la fonction pulmonaire et on l'arrête souvent quand c'est possible sans risque.",
  "body-composition": "Ce dont est fait le poids d'une personne : muscle, graisse sous la peau, graisse autour des organes. Elle prédit l'évolution du cancer bien mieux que le poids ou le BMI, et peut être lue sur des scanners CT de routine.",
  "bone-modifying-agents": "Zoledronic acid et denosumab réduisent les fractures, la compression de la moelle épinière et les douleurs osseuses dues aux métastases osseuses et au myélome, préviennent la perte osseuse induite par les traitements et, dans le cancer du sein postménopausique, réduisent modestement les récidives osseuses.",
  "bracanalysis-cdx": "Le test BRCA hérité qui décide qui peut recevoir des comprimés d'inhibiteurs de PARP pour les cancers de l'ovaire, du sein, du pancréas et de la prostate.",
  "bradley-monk": "Oncologue gynécologue qui a codirigé KEYNOTE-826, innovaTV 301 et KEYNOTE-A18, les essais qui ont refondé le traitement du cancer du col de l'utérus.",
  breakwater: "A doublé la survie, d'environ 15 à environ 30 mois, dans le sous-type génétique de plus mauvais pronostic du cancer de l'intestin en ajoutant deux médicaments ciblés à la chimiothérapie de première ligne.",
  "breast-cancer-trials": "Le groupe d'essais sur le cancer du sein d'Australie et de Nouvelle-Zélande, partenaire du Breast International Group dans SOFT/TEXT, APHINITY, OlympiA et POSITIVE.",
  brenetafusp: "Le successeur du tebentafusp : un récepteur de lymphocyte T soluble qui reconnaît un fragment de PRAME, une protéine présente dans la plupart des mélanomes et de nombreux autres cancers, et attire les lymphocytes T sur la tumeur.",
  "brian-druker": "Il a fait passer un inhibiteur de kinase mis au placard du laboratoire à un essai clinique en 1998, alors que peu de gens croyaient qu'un comprimé ciblé puisse fonctionner. L'imatinib a fait de la leucémie myéloïde chronique une maladie avec laquelle on vit, et il est devenu le modèle de la thérapie ciblée.",
  "btki-plus-venetoclax-fixed-duration": "Bloquer le signal de survie et retirer le bouclier contre la mort cellulaire en même temps, pendant environ un an, puis arrêter et rester en rémission pendant des années.",
  bwel: "BWEL est un essai portant sur plus de 3 000 femmes, qui teste si perdre du poids après le traitement d'un cancer du sein réduit les récidives. Le programme a permis une perte de poids ; l'effet sur les récidives n'a pas été clairement démontré lors de la première analyse.",
  "bystander-effect": "Lorsque la charge libérée s'échappe de la cellule ciblée et tue ses voisines, y compris des cellules dépourvues de la cible.",
  "cachexia-biology": "Le syndrome de dénutrition qui tue jusqu'à un tiers des patients atteints de cancer : les tumeurs envoient des signaux hormonaux (GDF-15, IL-6) qui coupent l'appétit et brûlent muscle et graisse. Le premier médicament à l'inverser, ponsegromab, a montré une prise de poids en 2024.",
  "cachexia-therapy": "Traiter le dépérissement qui tue de nombreux patients atteints de cancer, en bloquant l'hormone qui supprime l'appétit.",
  camizestrant: "Camizestrant est un dégradeur oral du récepteur des œstrogènes approuvé en septembre 2026 pour un nouveau type de décision : changer de traitement lorsqu'un test sanguin montre qu'une résistance se développe, avant que le cancer ne grossisse visiblement.",
  "camrelizumab-rivoceranib": "Une association chinoise d'immunothérapie et d'un comprimé anti-angiogénique qui a clairement battu le sorafenib dans le cancer du foie, mais qui reste non approuvée aux États-Unis après trois refus liés à la fabrication.",
  "cancer-council-australia": "L'association caritative fédérée australienne contre le cancer, qui finance la recherche, rédige les recommandations cliniques nationales et mène les campagnes de prévention à l'origine de la baisse du tabagisme et du mélanome en Australie.",
  "cancer-health-disparities": "Des différences systématiques dans qui développe un cancer, à quel stade il est découvert et qui survit, liées à l'origine ethnique, aux revenus, à la géographie, à l'assurance et au racisme structurel plutôt qu'à la seule biologie.",
  "cancer-institute-adyar": "Le deuxième plus ancien hôpital anticancéreux de l'Inde (1954), fondé par Muthulakshmi Reddy et dirigé pendant des décennies par V. Shanta, et siège du premier registre du cancer en population de l'Inde.",
  "cancer-neuroscience": "La neuroscience du cancer étudie la façon dont les tumeurs dialoguent avec les nerfs. Les nerfs se développent dans les tumeurs et leur envoient des signaux ; les tumeurs cérébrales vont jusqu'à se brancher sur les circuits neuronaux. Couper cette conversation avec des médicaments courants comme les bêtabloquants est aujourd'hui à l'essai.",
  "cancer-stage": "L'étendue de la propagation d'un cancer, du stade I (petit et localisé) au stade IV (disséminé vers des organes distants). Le stade est, à lui seul, le guide le plus fiable pour le traitement et le pronostic.",
  candiolo: "L'institut du cancer du Piémont, près de Turin, une référence mondiale en génomique du cancer colorectal, en xénogreffes dérivées de patients et en biologie de MET.",
  "capstone-1": "L'essai qui a ajouté adebrelimab, l'anticorps anti-PD-L1 de Hengrui, à la chimiothérapie dans le cancer du poumon à petites cellules, avec l'un des plus grands gains de survie observés dans cette maladie.",
  cbioportal: "cBioPortal permet de parcourir les mutations, le nombre de copies et l'expression de dizaines de milliers de tumeurs sans écrire de code.",
  "ccc-tuebingen": "Le centre de cancérologie de Tübingen, berceau des vaccins peptidiques contre le cancer et des sociétés issues de ses laboratoires Immatics et CureVac, avec une solide tradition en mélanome et en PET/MRI.",
  "ccc-vienna": "Le principal centre universitaire de cancérologie d'Autriche, à l'Hôpital général de Vienne, connu pour les essais du sein de l'ABCSG, la recherche sur les métastases cérébrales et le centre de thérapie par ions MedAustron.",
  "ccc-wuerzburg": "L'université où Röntgen a découvert les rayons X, aujourd'hui un centre mondial des CAR-T et des anticorps bispécifiques dans le myélome multiple, sous la direction de Hermann Einsele.",
  cclg: "L'organisme professionnel et le réseau d'essais du cancer de l'enfant du Royaume-Uni et d'Irlande ; presque chaque enfant traité pour un cancer au Royaume-Uni est pris en charge dans un centre CCLG.",
  cctg: "Le groupe national d'essais académiques du Canada, qui a mené l'essai CHALLENGE sur l'exercice physique et codirigé l'essai SABR-COMET sur l'oligométastase.",
  cd38: "CD38 est une enzyme de surface des cellules du myélome et la cible du daratumumab, désormais administré par une injection rapide sous la peau.",
  cdisc: "L'organisation à but non lucratif qui rédige les normes de données des essais cliniques (SDTM, ADaM, CDASH) que la FDA, la PMDA et la NMPA exigent pour chaque dossier de médicament anticancéreux.",
  "cell-cycle": "La séquence ordonnée que suit une cellule pour copier son ADN et se diviser en deux, avec des points de contrôle en chemin où elle s'arrête pour vérifier l'absence de dommages. Les cellules cancéreuses passent outre ces points de contrôle.",
  "centre-leon-berard": "Le centre de lutte contre le cancer de Lyon, référence mondiale pour les sarcomes et les cancers rares, dirigé par Jean-Yves Blay, qui préside également UNICANCER.",
  cervavac: "Le premier vaccin anti-HPV fabriqué en Inde, qui protège contre les deux types de virus responsables de la plupart des cancers du col de l'utérus et les deux types responsables des verrues génitales, à un prix conçu pour un programme national.",
};
